-- توضیح‌های کامل فارسی ماشینی (باقیمانده‌ی بدون متن رسمی) — ترجمه‌ی ماشینی با Gemini رایگان، ۲۰۲۶-۱۰-۲۵
-- ناقص: ۳۱ از ۴۸۳ توضیح (با gemini-3.5-flash)؛ بقیه پس از بازگشت سهمیه‌ی روزانه‌ی Gemini با فایل تکمیلی می‌آیند
-- فقط ردیف‌هایی را پر می‌کند که متن فارسی‌شان هنوز خالی است و منشأشان
-- خالی یا ماشینی است؛ متن رسمی و دستی هرگز بازنویسی نمی‌شود.
-- idempotent است و اجرای دوباره‌اش بی‌اثر است.
-- ترتیب اجرا: 0011_add-fa-translation-source.sql، بعد backfill-official-fa.sql، بعد این فایل.
UPDATE apps SET description_fa = 'Heliodos یک برنامه واقعیت افزوده (AR) است که مسیر حرکت خورشید و ماه را روی تصویر زنده دوربین شما قرار می‌دهد، تا بتوانید دقیقاً ببینید نور خورشید در هر زمان از سال کجا می‌تابد — درست از طریق منظره‌یاب گوشی شما.

در باغچه، زمین ساختمانی یا هر فضای باز دیگری بایستید، دوربین خود را به سمت آسمان بگیرید و بلافاصله کمان خورشید را برای انقلاب تابستانی، انقلاب زمستانی، اعتدالین و تاریخ و زمان فعلی، به همراه مسیر فعلی ماه — شامل تمامی موانع موجود در مسیر خورشید — مشاهده کنید.

ویژگی‌ها

مسیرهای واقعیت افزوده (AR) خورشید و ماه: مسیر خورشید برای انقلابین، اعتدالین و لحظه فعلی — به همراه مسیر فعلی ماه — مستقیماً روی تصویر زنده دوربین با علامت‌گذاری‌های ساعتی و برچسب‌های زمانی روی مسیرهای فعلی رسم می‌شوند.
مسیرهای قابل سفارشی‌سازی: مسیرهای مختلف را به‌صورت جداگانه روشن یا خاموش کنید و در تنظیمات برای هرکدام رنگ دلخواه انتخاب کنید.
موقعیت مکانی انعطاف‌پذیر: از موقعیت GPS شما به‌طور خودکار استفاده می‌کند یا به شما امکان می‌دهد هر نقطه‌ای از کره زمین را به‌صورت دستی تنظیم کنید.
زمان سفارشی: موقعیت خورشید را در هر ساعتی از شبانه‌روز شبیه‌سازی کنید، نه فقط در زمان حال.
انتخاب دوربین: با بزرگ‌نمایی لمسی (Pinch to zoom) بین دوربین‌های پشتی موجود (wide-angle، معمولی، telephoto) جابه‌جا شوید.

موارد استفاده

باغبانی: قبل از کاشت گیاهان، متوجه شوید کدام نقاط در تابستان در مقایسه با زمستان نور کامل خورشید را دریافت می‌کنند.
املاک و مستغلات: بررسی کنید که یک اتاق یا تراس در طول سال چه مقدار نور طبیعی دریافت می‌کند.
معماری و ساخت‌وساز: سایه‌بانی، پنجره‌ها و پنل‌های خورشیدی را با استفاده از داده‌های واقعی خورشید برنامه‌ریزی کنید.
عکاسی: لوکیشن‌ها را بررسی کرده و زوایای ساعات طلایی (Golden hour) را از قبل پیش‌بینی کنید.

برنامه Heliodos برای کارکرد صحیح به دسترسی‌های دوربین و موقعیت مکانی نیاز دارد. هیچ داده‌ای جمع‌آوری یا ارسال نمی‌شود.', description_fa_source = 'machine' WHERE package_name = 'eu.domob.heliodos' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'RPClient یک کلاینت نقش‌آفرینی و داستان‌نویسی با هوش مصنوعی است که از کارت‌های شخصیت رایج به سبک tavern و lorebookها پشتیبانی می‌کند. شخصیت‌های خودتان را بسازید، داستان‌های چندفصلی بنویسید، چت‌های تک‌به‌تک را آغاز کنید یا چت‌های گروهی بسازید که در آن چند شخصیت وارد یک داستان می‌شوند.

RPClient یک نسخه بازسازی‌شده از SillyTavern برای اندروید نیست. این برنامه یک اپلیکیشن نقش‌آفرینی و داستان‌نویسی با تمرکز بر موبایل است که از فرآیندهای آشنا مانند کارت‌های شخصیت، lorebookها، promptها و حافظه بلندمدت داستان پشتیبانی می‌کند و در عین حال رابط کاربری ویژه‌ای برای اندروید ارائه می‌دهد.

ویژگی‌های کلیدی:

- نوشتن و سازمان‌دهی داستان‌های چندفصلی با Story Studio (جلدها، فصل‌ها و promptهای ادامه)
- مشاهده استدلال و روند تفکر مدل به صورت لحظه‌ای در طول تولید متن
- پشتیبان‌گیری و به اشتراک‌گذاری داستان‌ها با خروجی گرفتن و وارد کردن آرشیو .rpstory
- وارد کردن کارت‌های شخصیت JSON و PNG (از جمله وارد کردن دسته‌ای)
- ساخت، ویرایش و مدیریت شخصیت‌های خودتان
- وارد کردن و مدیریت lorebookهای به سبک tavern (همراه با گروه‌های انحصار متقابل)
- شروع چت‌های تک‌به‌تک با شخصیت‌های هوش مصنوعی
- ایجاد چت‌های گروهی با حضور چند شخصیت
- تولید مجدد، ادامه دادن یا متوقف کردن پاسخ‌ها
- تولید متن از زاویه دید کاربر
- پیش بردن داستان‌های طولانی با حافظه خلاصه (summary memory)
- اختصاص مدل‌های مستقل به شخصیت‌ها و خلاصه‌های خاص
- وارد و خارج کردن تاریخچه چت‌های سازگار با SillyTavern (.jsonl)
- مدیریت promptها، تنظیمات شخصیت، پیام‌های خوش‌آمدگویی و context داستان
- اتصال به APIهای سازگار با OpenAI، Gemini، Claude، DeepSeek، OpenRouter و ارائه‌دهندگان اختصاصی
- چت‌ها، داستان‌ها، شخصیت‌ها و تنظیمات به صورت پیش‌فرض روی دستگاه شما ذخیره می‌شوند

برنامه RPClient شامل سرویس مدل هوش مصنوعی داخلی نیست. برای چت یا تولید داستان، باید ارائه‌دهنده مدل یا API key خود را تنظیم کنید. درخواست‌ها به ارائه‌دهنده‌ای که انتخاب می‌کنید ارسال می‌شوند، بنابراین لطفاً از سرویس‌های مورد اعتماد استفاده کنید.

برنامه RPClient یک اپلیکیشن رسمی SillyTavern برای اندروید نیست و هیچ وابستگی به OpenAI، Google، Anthropic، DeepSeek یا OpenRouter ندارد.', description_fa_source = 'machine' WHERE package_name = 'me.kafuuneko.rpclient' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
