امکان مسدود کردن اختیاری:
* شماره‌های منطبق با الگوهای REGEX، از جمله شماره‌های موجود در مخاطبین
* SIM 1/2 (Android 12+)

اگر برنامه تماس‌های مخاطبین را در Android 10 رد می‌کند، دسترسی Contacts را به‌صورت دستی در App info → Permissions مجاز کنید.

دسترسی‌ها:
* CALL_SCREENING - مسدود کردن یا مجاز کردن تماس
* READ_CALL_LOG - بررسی تماس با شماره یا پاسخ به آن و شمارش تعداد دفعات تماس آن شماره با شما در X دقیقه
* READ_SMS - بررسی ارسال پیام به شماره و دریافت پیام از آن
* RECEIVE_SMS - یافتن شماره‌های موبایل در پیام‌های ورودی
* NOTIFICATION_LISTENER - یافتن شماره‌های موبایل در اعلان‌ها
* READ_PHONE_STATE - بررسی اینکه شماره روی کدام SIM تماس می‌گیرد
* RECEIVE_BOOT_COMPLETED - حفظ عملیات پاک‌سازی شماره‌های منقضی‌شده پس از ریبوت دستگاه
* READ_CONTACTS - بررسی وجود شماره در مخاطبین در Android 10 یا مسدود کردن تماس‌های آن‌ها

این یک نرم‌افزار آزاد و متن‌باز است.
