این برنامه فقط محتوایی را که صراحتاً توسط کاربر به اشتراک گذاشته شده آپلود می‌کند و از هیچ‌گونه تبلیغات، ابزارهای تحلیلی (analytics)، ردیابی یا سرویس‌های انحصاری استفاده نمی‌کند.', description_fa_source = 'machine' WHERE package_name = 'net.chlup.myshare' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'ابزارهای ارتفاع‌سنج (altimeter) و واریومتر (variometer) هواپیما برای گوشی شما، ویژه علاقه‌مندان به هوانوردی. مناسب استفاده جهت مسیریابی نیست و صرفاً برای سرگرمی است!

سه منبع سنجش ارتفاع که با دکمه MODE جابه‌جا می‌شوند:

* GPS - ارتفاع مستقیم از گیرنده GPS. بسیار تقریبی.
* MAP - ارتفاع زمین (عوارض زمین) زیر موقعیت شما، از API ارتفاع Open-Meteo (GLO-90). این ارتفاع سطح زمین است، نه ارتفاع بالای سطح زمین.
* BAR - ارتفاع بارومتری، محاسبه‌شده از سنسور فشار دستگاه و فشار سطح دریا (QNH) که از api.met.no دریافت می‌شود. دقیق و سریع. اگر نمی‌خواهید دسترسی به موقعیت مکانی بدهید، QNH می‌تواند به‌صورت دستی تنظیم شود.

ارتفاع‌سنج دارای چیدمان کلاسیک سه عقربه‌ای (صدها / هزارها / ده هزارها) با پنجره Kollsman است. روی صفحه کلیک کنید تا زوم شود، دوباره کلیک کنید تا از زوم خارج شود. دکمه IMP/MET واحد را بین فوت و متر تغییر می‌دهد. فشار طولانی روی دکمه MODE یا IMP/MET، صفحه اشکال‌زدایی (debug overlay) همراه با نمودار نواری فشار را در حالت BAR فعال یا غیرفعال می‌کند.

حریم خصوصی:

* بدون حساب کاربری، بدون ابزارهای تحلیلی، بدون تبلیغات و بدون گزارش خرابی.
* تنظیمات فقط روی خود دستگاه ذخیره می‌شوند.
* مختصات گردشده تا چهار رقم اعشار به api.met.no (برای QNH) و api.open-meteo.com (برای ارتفاع زمین) ارسال می‌شوند؛ این دو سرویس آدرس IP شما را نیز مشاهده می‌کنند.
* به جز این دو استعلام QNH و ارتفاع زمین، همه چیز کاملاً آفلاین است.

بدون Google Play Services، بدون کتابخانه‌های انحصاری، و بدون SDKهای کدبسته.', description_fa_source = 'machine' WHERE package_name = 'no.falkp.vario' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
