UPDATE apps SET description_fa = 'aTalk یک کلاینت XMPP است که از قابلیت‌های زیر پشتیبانی می‌کند:

* پیام‌رسانی فوری به صورت متن ساده و رمزنگاری سرتاسری (End-to-End) با OMEMO
* احراز هویت گواهی SSL، پیاده‌سازی امنیت DNSSEC و DANE برای برقراری اتصال امن‌تر
* رمزنگاری OMEMO در نشست‌های چت گروهی جهت افزایش حریم خصوصی و امنیت
* اشتراک‌گذاری فایل‌های رسانه‌ای OMEMO برای همه فایل‌ها شامل استیکرها، Bitmoji و محتوای غنی Emoji
* پشتیبانی از آپلود فایل http برای اشتراک‌گذاری فایل با مخاطبان آفلاین و در چت گروهی
* پشتیبانی از اشتراک‌گذاری استیکرها، Bitmoji و محتوای غنی Emoji از طریق Google Gboard
* ارسال و دریافت فایل برای انواع سندها و تصاویر همراه با پیش‌نمایش بندانگشتی و پویانمایی gif
* پذیرش خودکار انتقال فایل با قابلیت تنظیم حداکثر حجم فایل
* پیاده‌سازی الگوریتم انتقال فایل با قابلیت تحمل خطا (fault-tolerance)، از طریق پروتکل‌های Jingle File Transfer، Legacy In-Band/SOCK5 Bytestreams و HttpFileUpload برای تسهیل و افزایش قابلیت اطمینان اشتراک‌گذاری فایل
* بهبود و هماهنگ‌سازی رابط کاربری برای اشتراک‌گذاری فایل در چت و chatRoom
* پشتیبانی از اشتراک‌گذاری، نقل‌قول (quote) و هدایت (forward) پیام‌ها و رسانه‌ها همراه با پیش‌نمایش قبل از ارسال
* پشتیبانی از چند نمونه (multi-instances) پخش‌کننده رسانه صوتی با توابع: پخش، توقف موقت، ادامه، توقف و پیمایش (Seek)
* پشتیبانی از نشان‌گر پیام‌های خوانده‌نشده در لیست مخاطبان و chatRoom
* گزینه انتخابی کاربر برای اعلانات heads-up و ساعات سکوت (quiet hours)
* اشتراک‌گذاری لینک‌های شبکه‌های اجتماعی همراه با تصویر بندانگشتی و عنوان
* پشتیبانی از تبدیل متن به گفتار (Text to Speech) و رابط کاربری تشخیص گفتار با امکان فعال‌سازی برای هر نشست چت (مخاطب و چت گروهی)
* XEP-0012: زمان آخرین فعالیت (Last Activity) مرتبط با مخاطبان
* XEP-0048: نشانک‌ها (Bookmarks) برای اتاق کنفرانس و autoJoin هنگام ورود
* XEP-0070: تایید درخواست‌های HTTP از طریق موجودیت XMPP برای احراز هویت کاربر بدون نیاز به ورود رمز عبور
* XEP-0071: پشتیبانی XHTML-IM از پیام‌های چت حاوی علامت‌گذاری متنی سبک
* XEP-0085: اعلانات وضعیت چت (Chat State Notifications)
* XEP-0124: جریان‌های دوطرفه روی HTTP همگام (BOSH) با پشتیبانی از Proxy
* XEP-0178: استفاده از SASL EXTERNAL با گواهی‌های TLS برای احراز هویت کلاینت
* XEP-0184: رسید تحویل پیام (Message Delivery Receipts) با امکان فعال/غیرفعال‌سازی توسط کاربر
* XEP-0215: کشف سرویس خارجی (External Service Discovery)
* XEP-0251: انتقال نشست Jingle: پشتیبانی از انتقال تماس Unattended و Attended
* XEP-0391: انتقال‌های رمزنگاری‌شده Jingle برای اشتراک‌گذاری فایل‌های رسانه‌ای رمزنگاری‌شده با OMEMO
* پیاده‌سازی انتظار تماس (call waiting) برای پذیرش تماس ورودی دوم با قرار دادن تماس در حال جریان روی پشت خط (hold) و امکان جابه‌جایی بین تماس‌ها
* پیاده‌سازی تلفن درگاه Jabber VoIP-PBX جهت امکان برقراری تماس تلفنی PBX از طریق درگاه سرویس
* ورود یا ساخت اتاق با پشتیبانی کامل از پیکربندی اتاق برای مالک
* رابط کاربری یکپارچه اتاق محافظت‌شده با کپچا (captcha) همراه با تلاش مجدد در صورت شکست
* پشتیبانی از تماس صوتی و تصویری با حالت‌های رمزنگاری ZRTP، SDES و DTLS SRTP
* الگوریتم‌های رمزنگاری ZRTP از سایفرهای SHA-2 384، 256bit AES256 & TWOFISH-256 و منحنی بیضوی Curve 25519 استفاده می‌کنند
* رمزنگاری SDES با AES256 و AES192، شتاب‌دهی با استفاده از OpenSSL
* پشتیبانی از نشست‌های هم‌زمان تماس رسانه‌ای و چت متنی
* پیاده‌سازی منحصربه‌فرد GPS-Location به عنوان ابزار مستقل، ارسال موقعیت مکانی به مخاطب دلخواه برای ردگیری لحظه‌ای یا انیمیشن بازپخش
* نمای خیابانی ۳۶۰ درجه از موقعیت فعلی شما جهت تورهای خودگردان. نمای خیابان جهت دید شما را دنبال و ردگیری می‌کند
* دمو داخلی برای ویژگی‌های GPS-Location
* ویرایشگر عکس داخلی با قابلیت زوم و برش (crop)، کاربر می‌تواند به راحتی آواتار خود را به‌روزرسانی کند
* اصلاح آخرین پیام، پیام‌های همگام (message carbons) و پیام‌های آفلاین (OMEMO)
