* پشتیبانی از ثبت‌نام درون‌باندی (In-Band Registration) با گزینه کپچا
* امکان ساخت چند حساب کاربری
* پشتیبانی از تم‌های قابل انتخاب توسط کاربر
* پشتیبانی از رابط کاربری چندزبانه (باهاسا اندونزیایی، انگلیسی، آلمانی، پرتغالی، روسی، اسلواکی و اسپانیایی)', description_fa_source = 'machine' WHERE package_name = 'org.atalk.android' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'Snow یک بسته آیکون تک‌رنگ و ساده است که از Frost فورک شده است. Snow یک نرم‌افزار آزاد و متن‌باز (FOSS) است و عمدتاً آیکون‌های برنامه‌های متن‌باز موجود در F-Droid را ارائه می‌دهد (اما برنامه‌های متعدد دیگری نیز در این بسته وجود دارد). هدف از طراحی آن، سادگی همراه با شکل‌های به‌راحتی قابل تشخیص است.

Snow شامل پشتیبانی از لانچرهای متعددی مانند Trebuchet، KISS، Nova، Apex، Holo، ZenUI، ADW و بسیاری دیگر است. نحوه نصب به لانچر شما بستگی دارد و احتمالاً در بخش تنظیمات قرار دارد.', description_fa_source = 'machine' WHERE package_name = 'org.baitmooth.snow' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'Birthday Adapter تاریخ تولدها، سالگردها و سایر رویدادها را از مخاطبان شما به تقویم‌های Android منتقل می‌کند. بر خلاف برنامه‌های دیگر، این برنامه یک تقویم اختصاصی درون سیستم شما ایجاد می‌کند تا بتوانید تمام تاریخ‌های مربوط به مخاطبان خود را در کنار برنامه روزانه خود در برنامه تقویم دلخواهتان مشاهده کنید.

ویژگی‌ها
* مبتنی بر دفترچه تلفن: تاریخ تولدها را مستقیماً در مخاطبان خود ذخیره کنید - بدون نیاز به نگهداری فهرست‌های دستی یا مدیریت ورودی‌های تکراری.
* فیلترسازی: حساب‌ها یا گروه‌های مخاطبی را که می‌خواهید در تقویم خود ببینید، انتخاب کنید.
* یکپارچه‌سازی: تاریخ تولد مخاطبان خود را مستقیماً در برنامه تقویم مورد علاقه‌تان مشاهده کنید؛ سازمان‌دهی‌شده در یک تقویم مجزا که می‌توانید هر زمان بخواهید آن را نمایش دهید، پنهان کنید یا در کنار برنامه روزانه‌تان ببینید.
* نمایش سن: با اضافه شدن خودکار سن به هر رویداد، همیشه می‌دانید چه سالگرد مهمی در پیش است.
* فراتر از تولدها: هر تاریخ با برچسب سفارشی را از دفترچه تلفن خود همگام‌سازی کنید - عالی برای پیگیری سالگردهای مخاطبان یا تولد فرزندان و همسران آن‌ها.
* یادآوری‌ها: به تعداد دلخواه برای رویدادهای خود یادآوری تنظیم کنید.
* نشانگرهای سالگرد: رویدادهای مهم و سالگردهای بزرگ را به راحتی تشخیص دهید.
* سفارشی‌سازی: عناوین رویدادها را به دلخواه خود تغییر دهید و انتخاب کنید کدام انواع رویداد باید اعلانی را تحریک کنند.
* شخصی‌سازی: از ابزار انتخاب رنگ استفاده کنید تا ظاهر تقویم تولد خود را مطابق با سلیقه شخصی‌تان طراحی کنید.
* همگام‌سازی پس‌زمینه: تقویم شما با به‌روزرسانی‌های منظم در پس‌زمینه همگام باقی می‌ماند.

