UPDATE apps SET description_fa = 'Brogue CE نسخه نگهداری‌شده توسط جامعه کاربران از بازی Brogue است؛ یک بازی تک‌نفره روگ‌لایک در سبک سیاه‌چال‌پیمایی (dungeon crawling). به سیاه‌چاله‌های مرگ فرود آیید، طلسم Yendor را بازپسرانید و به سطح زمین بازگردید. هر دور بازی به صورت رویه‌ای (procedurally) تولید می‌شود و دارای گیم‌پلی تاکتیکی غنی، نورپردازی زیبای ASCII-art و رابط کاربری شیک است.

