UPDATE apps SET description_fa = 'رابط کامپیوتر سفینه‌ای c-base - کنترل c-base از داخل جیب شما!

توجه: این برنامه فقط از داخل وای‌فای c-base-crew قابل استفاده است. اگر نمی‌دانید این به چه معناست، c-beam را دانلود نکنید.

اگر هنوز با ما هستید، این مجموعه ویژگی‌ها برای لذت اطلاعاتی شما ارائه می‌شود:

