UPDATE apps SET description_fa = 'OpenSyncedLists روشی سریع و خصوصی برای تحت کنترل داشتن تمام چک‌لیست‌ها، کارها (to-do) و پروژه‌های کوچک است – همگام‌سازی‌شده در تمام دستگاه‌های شما و رمزنگاری‌شده به صورت سرتاسری (end-to-end).

چه خرید هفتگی باشد، چه لیست آرزوها یا کارهای پروژه بعدی شما: در چند ثانیه یک لیست بسازید، آن را به روش خود مرتب کنید و همان‌طور که پیش می‌روید موارد را علامت بزنید. وقتی کارتان تمام شد، تمام لیست را با یک ضربه بازنشانی کنید و از نو شروع کنید.

چرا عاشق آن خواهید شد

• مرتب‌سازی آسان – هر موردی را بکشید و رها کنید (drag and drop)، یا آن را مستقیماً به ابتدا یا انتهای لیست ببرید.
• نمای کلی و شفاف – برچسب‌ها، شمارنده‌های پیشرفت و حالت فشرده باعث می‌شوند لیست‌های شلوغ به راحتی قابل مرور باشند.
• مرتب باقی می‌ماند – موارد علامت‌خورده به کنار می‌روند اما جایگاه خود را حفظ می‌کنند، آماده برای استفاده مجدد.
• بازنشانی با یک ضربه – تمام تیک‌ها را یک‌باره پاک کنید و همان لیست را دوباره اجرا کنید.
• عالی برای پروژه‌های کوچک – کارها را با برچسب‌های اختصاصی خود گروه‌بندی کنید و موارد باقی‌مانده را پیگیری نمایید.

حریم خصوصی از ابتدا (PRIVACY BY DESIGN)

• همگام‌سازی رمزنگاری‌شده سرتاسری – لیست‌های شما روی دستگاه خودتان رمزنگاری می‌شوند.
• شخصی‌میزبان (Self-hosted) – همگام‌سازی را روی سرور خودتان اجرا کنید، در صورت تمایل حتی برای هر لیست از سرور متفاوتی استفاده کنید.
• اپراتور سرور هرگز نمی‌تواند لیست‌های شما را بخواند. بدون حساب کاربری، بدون ردگیری، بدون جمع‌آوری اطلاعات.

طراحی‌شده متناسب با شما

• حالت دست‌چپ و کنترل‌های قابل تنظیم (با یا بدون دکمه).
• اندازه فونت قابل تنظیم برای عناصر لیست.
• اشتراک‌گذاری لیست‌ها از طریق URL.
• خروجی گرفتن به صورت Markdown، کلیپ‌بورد، پیام، JSON و موارد دیگر.
• رایگان و متن‌باز.

