برای دست‌یابی به این هدف، این برنامه از داده‌های منابع مختلفی استفاده می‌کند:
- آمریکا: Bureau of Labor Statistics (Historical CPI-U)، https://www.bls.gov/cpi/
- بریتانیا: Office for National Statistics، https://www.ons.gov.uk/economy/inflationandpriceindices/timeseries/cdko/mm23
- فرانسه: INSEE، https://www.insee.fr/fr/statistiques/serie/010605954
