UPDATE apps SET description_fa = 'برنامه Étagère کتابخانه Calibre ذخیره‌شده در Nextcloud شخصی شما را مرور می‌کند، اطلاعات کامل هر کتاب را نشان می‌دهد و فایل‌ها را دانلود می‌کند. این برنامه کتاب‌ها را نمی‌خواند — این کار بر عهده برنامه کتاب‌خوان شماست و شما حتماً یکی از آن‌ها را دارید و دوستش دارید.

قابلیت‌ها

* ورود به Nextcloud از طریق مرورگر، با استفاده از رمز عبور قابل لغو برنامه
* خواندن کاتالوگ Calibre و در دسترس نگه داشتن آن به صورت آفلاین
* جلدها، نویسندگان، مجموعه‌ها، امتیازها، ناشر، زبان‌ها، برچسب‌ها، شناسه، توضیحات
* جستجو، مرتب‌سازی و فیلتر بر اساس برچسب، نویسنده یا مجموعه
* دانلود فایل‌های EPUB و هر فرمت دیگری که Calibre دارد، در پس‌زمینه
* ارائه کتابخانه به یک کتاب‌خوان الکترونیکی (e-reader) از طریق Wi-Fi، برای دستگاه‌هایی که می‌توانند از یک صفحه وب دانلود کنند

آنچه انجام نمی‌دهد

* فاقد کتاب‌خوان داخلی
* هرگز روی سرور شما چیزی نمی‌نویسد — کتابخانه فقط‌خواندنی است
* بدون نیاز به حساب کاربری، بدون دورسنجی (telemetry) و بدون تبلیغات

نحوه کارکرد

یک کتابخانه Calibre پوشه‌ای است حاوی کاتالوگ metadata.db و یک زیرپوشه برای هر کتاب. برنامه Étagère آن فایل را از طریق WebDAV پیدا می‌کند، یک بار دانلود می‌کند و آن را به صورت محلی می‌خواند. جلدها و فایل‌های کتاب بنا به درخواست دریافت می‌شوند، نه به صورت یک‌جا. کاتالوگ تنها زمانی دوباره دانلود می‌شود که واقعاً تغییر کرده باشد، بنابراین برنامه به صورت آفلاین قابل استفاده باقی می‌ماند.

اشتراک‌گذاری با کتاب‌خوان الکترونیکی

بسیاری از کتاب‌خوان‌های الکترونیکی می‌توانند فایلی را از یک صفحه وب دانلود کنند اما نمی‌توانند کاتالوگ‌های OPDS را بخوانند. Étagère گوشی شما را به یک وب‌سرور کوچک در شبکه محلی‌تان تبدیل می‌کند، با صفحاتی که برای جوهر الکترونیکی (e-ink) طراحی شده‌اند: بدون JavaScript، بدون تصویر بندانگشتی در فهرست‌ها، سیاه و سفید خالص و دکمه‌های لمسی بزرگ. همچنین یک کتاب فردی می‌تواند تحت یک آدرس کوتاه ارائه شود تا تایپ آن روی کیبورد جوهر الکترونیکی آسان باشد.

ترافیک روی آن سرور محلی رمزنگاری نشده است، زیرا مرورگرهای کتاب‌خوان‌های الکترونیکی به‌ندرتاً از پروتکل‌های دیگر پشتیبانی می‌کنند. از آن در شبکه‌ای که به آن اعتماد دارید استفاده کنید.

پیش‌نیازها

یک حساب Nextcloud و یک کتابخانه Calibre ذخیره‌شده روی آن. برنامه Étagère کتابخانه ایجاد نمی‌کند؛ برای این کار از Calibre روی رایانه استفاده کنید.

