UPDATE apps SET description_fa = 'برنامه Mirror یک اپلیکیشن پشتیبان‌گیری از نوع آینه‌ای (mirror) و چندپروتکله برای اندروید است.
این برنامه به گونه‌ای طراحی شده که ساده‌تر و سبک‌تر از نرم‌افزارهای همگام‌سازی (synchronization) باشد و به شما امکان می‌دهد به‌جای سرویس‌های ابری شخص ثالث، از زیرساخت اختصاصی خود استفاده کنید.

می‌توانید چندین پشتیبان‌گیری را به شکل زیر پیکربندی کنید:

- انتخاب پوشه مبدأ
- انتخاب پوشه مقصد
- انتخاب گزینه‌های فیلتر (اختیاری)
- پیکربندی زمان‌بندی خودکار (اختیاری)

برنامه Mirror محتوای هر دو پوشه را تحلیل و مقایسه کرده و ساختار پوشه مبدأ (زیرپوشه‌ها و فایل‌ها) را با رعایت گزینه‌های فیلتری که انتخاب کرده‌اید، در پوشه مقصد بازسازی می‌کند.

مبدأ و مقصد می‌توانند در مکان‌های زیر قرار داشته باشند:

- حافظه داخلی یا خارجی دستگاه شما
- یک اشتراک NFS
- یک اشتراک SMB
- یک سرور FTP یا FTPS
- یک سرور SFTP
- یک سرور WebDAV

امنیت و حریم خصوصی

- ذخیره‌سازی محلی: اطلاعات حساس رمزنگاری شده (AES-GCM + Android KeyStore) و با استفاده از پایگاه داده Room به صورت محلی روی دستگاه شما ذخیره می‌شوند.
- بدون ردیابی: این برنامه فاقد هرگونه ابزار تحلیلی (analytics)، ردیاب، تبلیغات یا کیت‌های توسعه نرم‌افزار (SDK) انحصاری است.
- متن‌باز (Open Source): برنامه Mirror یک پروژه مستقل است. سورس کد آن جهت شفافیت و بررسی، روی GitHub در دسترس است.', description_fa_source = 'machine' WHERE package_name = 'fr.hellpc.mirror' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
