برنامه KeepOn به شما امکان می‌دهد صفحه نمایش دستگاه خود را برای مدت زمان دلخواه روشن نگه دارید و همچنین پس از خاموش شدن صفحه، به طور خودکار به تنظیمات پیش‌فرض بازگردید.
