 - android.permission.REQUEST_IGNORE_BATTERY_OPTIMIZATIONS: مورد نیاز برای جلوگیری از بستن برنامه KeepOn توسط اندروید در زمان اجرا
 - android.permission.POST_NOTIFICATIONS: مورد نیاز برای اجازه دادن به KeepOn جهت نمایش اعلان در زمان اجرا

