UPDATE apps SET description_fa = 'Drausible آمار Plausible Analytics شما را روی گوشی Android نشان می‌دهد. سرور را اضافه کنید — چه سرویس ابری plausible.io باشد چه نسخه Community Edition که خودتان روی سخت‌افزارتان اجرا می‌کنید — سایت‌های مورد نظرتان را اضافه کنید و بدون نیاز به باز کردن مرورگر، به داشبورد دسترسی داشته باشید.

بدون نیاز به حساب کاربری، فقط کافی است API key بگیرید و آن را وارد برنامه کنید.
از آنجا که فهرست کردن سایت‌ها بخشی از API نسخه Community Edition نیست، باید سایت‌ها را به صورت دستی اضافه کنید.

آمار به ازای هر سایت:

* بازدیدکنندگان، بازدیدها، pageviewها، بازدید به ازای هر ورود، bounce rate و میانگین مدت زمان بازدید
* نمودار بازدیدکنندگان در طول زمان، دسته‌بندی‌شده بر اساس ساعت هنگام بررسی یک روز مشخص
* صفحات، منابع، کشورها و دستگاه‌های برتر با امکان جابه‌جایی بین نوع دستگاه، مرورگر و سیستم‌عامل
* تعداد بازدیدکنندگان در لحظه، که تا زمان باز بودن صفحه به‌روز نگه‌داشته می‌شود

چند نکته مهم اگر خودتان سرور را میزبانی (self-host) می‌کنید:

* سرورهایی که برای v2 stats API خیلی قدیمی هستند، به‌طور خودکار به v1 تغییر می‌یابند
* HTTP معمولی هم کار می‌کند، زیرا نمونه‌های روی شبکه خانگی معمولاً بدون TLS اجرا می‌شوند
* هر سرور می‌تواند از پروکسی SOCKS5 مجزای خود عبور کند، بنابراین آدرس‌های onion. با Orbot کار می‌کنند', description_fa_source = 'machine' WHERE package_name = 'io.github.cheesymoon.drausible' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'نسخه اولیه: پیش‌بینی‌ها آزمایشی هستند — همواره زمان‌ها و مسیرها را با برنامه‌های رسمی DB بررسی و تطبیق دهید.

برنامه BayesianBahn زمان واقعی رسیدن شما را پیش‌بینی می‌کند — به صورت یک توزیع احتمالی کامل، نه فقط یک عدد واحد.

مبدا، مقصد و زمان حرکت (حتی سفرهای آینده) را وارد کنید: برنامه قطارهای مستقیم و سفرهای با یک تعویض قطار را جستجو می‌کند — مسیرهایی که به دو یا چند تعویض نیاز دارند هنوز پوشش داده نمی‌شوند، بنابراین گاهی اوقات مسیرهای کمتری نسبت به برنامه‌های خود DB پیدا می‌کند. برای هر گزینه موارد زیر نشان داده می‌شود:

* میانه زمان پیش‌بینی‌شده برای رسیدن به مقصد،
* یک بازه اطمینان ۸۰ درصدی،
* توزیع کامل تاخیر به صورت نمودار،
* احتمال رسیدن به هر قطار تعویضی،
* فیلتر Deutschland-Ticket برای محدود کردن مسیرها به قطارهای منطقه‌ای.

تعویض‌های قطار با استفاده از قضیه بیز محاسبه می‌شوند: شما سوار اولین قطار تعویضی می‌شوید که هنوز حرکت نکرده است — بنابراین قطاری که تاخیر داشته همچنان قابل رسیدن محسوب می‌شود و از دست دادن یک قطار تعویضی به‌طور واقعی کل توزیع احتمالات را جابه‌جا می‌کند. تابلوهای زنده ایستگاه‌ها و پیش‌بینی‌های مربوط به هر قطار (از جمله نرخ لغو حرکت) نیز در دسترس است.

پیش‌بینی‌ها تجربی هستند: آن‌ها از ماه‌ها داده‌های واقعیِ حرکت‌های قبلی همان قطار در همان ایستگاه به دست آمده‌اند (جمع‌آوری‌شده از API عمومی IRIS متعلق به Deutsche Bahn، با مجوز CC BY 4.0) که بر اساس تازگی داده‌ها و روز هفته دوباره وزن‌دهی شده‌اند. وقتی DB تاخیر واقعی را گزارش می‌دهد، پیش‌بینی بر اساس آن مبنا‌سازی می‌شود؛ اما وقتی چیزی گزارش نمی‌کند — که برای اکثر قطارها تا اندکی قبل از حرکت همین‌طور است — تاریخچه به‌تنهایی مبنا قرار می‌گیرد، که به‌طور قابل‌توجهی دقیق‌تر از در نظر گرفتن برنامه زمانی به عنوان پیش‌بینی است. تاریخچه تاخیرها درون برنامه به‌روزرسانی می‌شود — انتشار روزانه یک فایل داده کوچک، پیش‌بینی‌ها را تا حد یک روز تازه نگه می‌دارد. برای قطارهای بدون تاریخچه نیز یک تخمین پیشین بیزی (Bayesian prior) ارائه می‌شود.

این برنامه فقط با آدرس عمومی و بدون کلیدِ برنامه زمانی IRIS و انتشار داده‌های خود پروژه ارتباط برقرار می‌کند، به هیچ حساب کاربری، API key، خدمات Google نیاز ندارد و هیچ داده‌ای جمع‌آوری نمی‌کند.', description_fa_source = 'machine' WHERE package_name = 'io.github.derweh.bayesianbahn' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'Lunachron یک برنامه مکمل رایگان و متن‌باز برای بازی مینیاتوری رومیزی Moonstone ساخته Goblin King Games است.

پیگیری همه‌چیز در طول بازی:
• نشانگرهای سلامتی با دسته‌بندی‌های مجزا برای خوانش سریع
• شمارنده‌های انرژی، شمارش سنگ‌های ماه (Moonstone) و نشانگرهای قابلیت‌های یک‌بار در هر نوبت
• دو حالت چیدمان — شبکه‌ای فشرده برای مرور سریع، و لیست با جزئیات برای اطلاعات کامل کارت‌ها
• حالت کم‌جزئیات برای بازیکنانی که ترجیح می‌دهند منابع را به صورت فیزیکی پیگیری کنند

ساخت و مدیریت مجموعه:
• آرشیو کامل شخصیت‌ها همراه با ویژگی‌ها، قابلیت‌ها و اطلاعات فرقه (Faction)
• کتابخانه کارت‌های ارتقا با قابلیت جستجو و فیلتر
• ابزار ساخت گروه (Troupe) با قابلیت اشتراک‌گذاری از طریق QR code — اسکن کد برای وارد کردن آنی ترکیب تیم دوست‌تان
• مرجع کارت‌های کمپین

حالت‌های بازی:
• حالت تک‌نفره برای پیگیری فقط یک گروه
• بازی چندنفره محلی و دوستانه از طریق Wi-Fi (بدون نیاز به اینترنت یا حساب ابری) برای همگام‌سازی خودکار گروه‌ها
• مدیریت جدول رقابت‌های تورنمنت محلی

کمپین‌ها:
• پیگیری پیشرفت کمپین‌های در حال جریان، جدول رده‌بندی و تاریخچه بازی‌ها

تمام داده‌های بازی درون خود برنامه گنجانده شده‌اند و به صورت کاملاً آفلاین کار می‌کنند. تصاویر اختیاری پرتره و به‌روزرسانی داده‌ها قابل دریافت از مخزن داده‌های آزاد هستند — پیش از هرگونه دانلود، همیشه از شما تایید گرفته می‌شود.

بدون نیاز به حساب کاربری، بدون تبلیغات، بدون ردیابی و بدون نیاز به سرویس‌های انحصاری.

