UPDATE apps SET description_fa = 'یک ردیاب تمرینات با وزن بدن با تمرکز بر حفظ حریم خصوصی. همه چیز را شخصی‌سازی کنید — حرکت‌ها، روش‌های تمرینی و روند کار — تا دقیقاً با نیازهای شما هماهنگ شود.

بدون قالب‌های پیش‌فرض و غیرقابل تغییر. برنامه را با سبک تمرینی خود هماهنگ کنید.

برنامه‌ریزی (To Do)

• برنامه‌ریزی تمرین به صورت لیست و ورود مستقیم با یک ضربه
• زمان‌بندی تکرارها بر اساس روزهای هفته برای خودکارسازی برنامه هفتگی

حالت ثبت (Record Mode)

• ثبت سریع تمرینات پس از اتمام ورزش

حالت تمرین (Workout Mode)

• تمرین هدایت‌شده و خودکار همراه با تایمرهای داخلی
• تکی (Single): شمارش تکرارها با کمک تایمر و ردیابی نگه داشتن ایزومتریک
• برنامه‌ای (Program): ساخت و اجرای ترتیبی برنامه‌های چندحرکتی
• اینتروال (Interval): چرخه‌های زمان‌بندی‌شده تمرین/استراحت با قابلیت شخصی‌سازی تعداد دورها
• برنامه‌ها و اینتروال‌ها با ترکیب آزادانه حرکت‌های اختصاصی خودتان ساخته می‌شوند

ایجاد حرکت تمرینی

• ایجاد هر نوع حرکت با نام دلخواه و دسته‌بندی آن‌ها در گروه‌ها
• انتخاب ردیابی بر اساس تکرار (دینامیک) یا بر اساس زمان (ایزومتریک)
• پشتیبانی از حرکت‌های یک‌طرفه (Unilateral)
• پیشرفت ۱۰ سطحی متناسب با روش تمرینی شما
• قابلیت اختیاری ثبت مسافت، وزن و میزان کمک (Assistance)
• علامت‌گذاری حرکت‌های مورد علاقه (★) برای دسترسی سریع
• امکان افزودن یادداشت و توضیحات اختیاری به هر حرکت

ردیابی پیشرفت

• تقویم: مشاهده فعالیت‌های تمرینی در یک نگاه
• لیست: مرور تمامی جلسات تمرینی به ترتیب زمانی
• نمودار: مشاهده روندها با آمار میانگین، حداکثر و مجموع
• چالش: ردیابی میزان دستیابی به اهداف با کدهای رنگی
• فیلترهای بازه زمانی (۱ هفته، ۱ ماه، ۳ ماه)

مدیریت داده‌ها

• خروجی و ورودی گرفتن (Export/Import) با فرمت JSON و CSV
• داده‌های شما روی دستگاه خودتان باقی می‌ماند و نیازی به اینترنت نیست

روش‌های Convict Conditioning، StartBodyweight، RR (Recommended Routine)، HIIT، تمرینات دایره‌ای (circuit training) — روش تمرینی شما هر چه که باشد، این برنامه با شما هماهنگ می‌شود.', description_fa_source = 'machine' WHERE package_name = 'io.github.gonbei774.calisthenicsmemory' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'Meditate یک تایمر مدیتیشن کاربرپسند است که به شما کمک می‌کند یک روال تمرینی منظم بسازید — بدون نیاز به حساب کاربری، بدون جمع‌آوری اطلاعات (telemetry) و با کنترل کامل روی داده‌های شخصی‌تان.

تایمر

* حالت‌های شمارش معکوس، کرونومتر و تنفس مربعی (Box Breath)
* تنفس مربعی: انتخاب یک الگوی آماده (۴-۴-۴-۴، ۴-۷-۸-۰، …) یا تنظیم دستی هر مرحله، همراه با یک نقطه آرام که هنگام تنفس روی مربع حرکت می‌کند
* حالت هدایت‌شده (Guided): وارد کردن فایل‌های صوتی دلخواه و پخش صدای زنگ با پایان یافتن ترک
* زنگ شروع، زنگ‌های بین زمانی (ثابت، دوره‌ای یا تصادفی) و زنگ پایان — صدا، ویبره یا هر دو، با فایل صوتی و الگوهای ویبره دلخواه شما
* تنظیمات پیش‌فرض برای نشست‌های منظم شما، به همراه ویجت صفحه اصلی برای شروع تنها با یک لمس

تاریخچه و آمار

* ثبت جلسات دسته‌بندی‌شده بر اساس تاریخ همراه با برچسب‌ها و یادداشت‌ها، با قابلیت کشیدن برای حذف (Swipe) به همراه امکان بازگردانی (Undo)
* حلقه هدف روزانه، نقشه حرارتی (Heatmap) مشارکت ۱۳ هفته‌ای، نمودارهای میله‌ای/خطی، و آمار و مجموع زمان‌ها به تفکیک برچسب
* خروجی و ورودی CSV، و وارد کردن داده‌ها از Insight Timer

همگام‌سازی

* همگام‌سازی اختیاری بین دستگاه‌های شما از طریق Nextcloud شخصی‌تان — همچنین با نسخه GNOME/Linux برنامه‌ی Meditate که از هسته یکسانی استفاده می‌کند سازگار است
* اولویت با حالت آفلاین (Offline-first): همه‌چیز بدون اتصال به شبکه کار می‌کند؛ همگام‌سازی به محض آنلاین شدن مجدد، تغییرات را ادغام می‌کند

حریم خصوصی

جلسات در یک پایگاه داده محلی روی دستگاه شما ذخیره می‌شوند. تنها ارتباط شبکه‌ای، با سرور Nextcloud است که خودتان تنظیم می‌کنید — هیچ سرور دیگری، هیچ بخش آنالیز، و هیچ ردگیری (Tracking) وجود ندارد.', description_fa_source = 'machine' WHERE package_name = 'io.github.janekbt.Meditate' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
