• مدیریت وظایف با مشخص کردن تعداد stanzaهای تخمینی و تکمیل‌شده
• آمارها شامل مجموع روزانه و هفتگی، زنجیره‌های استمرار (streaks) و نقشه حرارتی (heatmap) سالانه
• چندین چیدمان مختلف برای تایمر و تم‌های رنگی متنوع
