UPDATE apps SET description_fa = 'liftmath همان ماشین‌حسابی است که بین ست‌ها لازم دارید. چند کار محدود انجام می‌دهد، اما آن‌ها را درست و اصولی انجام می‌دهد.

یک تکرار بیشینه (One-rep max): هر ستی را که تازه زده‌اید وارد کنید تا شش فرمول معتبر را اجرا کند و میانه‌ (median) آن‌ها را نشان دهد. RPE یا تکرارهای ذخیره (reps in reserve) را اضافه کنید تا تکرارهایی را که در توان داشتید هم محاسبه کند. نمودار درصدیِ زیر آن، وزنه‌ها را از ۱۰۰٪ تا ۵۰٪ به شما می‌دهد که بر اساس صفحه‌های واقعی شما گرد شده‌اند. با لمس هر ردیف می‌توانید آن را بارگذاری کنید.

صفحه‌ها (Plates): وزنه هدف را تایپ کنید تا به شما بگوید در هر طرف چه صفحه‌هایی بگذارید و میله را تصویرسازی کند. این قابلیت با میله استاندارد، میله ۱۵ کیلوگرمی بانوان، صفحه‌های متری یا دقیقاً همان صفحه‌هایی که در خانه دارید کار می‌کند. حالت گرم کردن را فعال کنید تا ست‌های گرم کردن را تا رسیدن به وزنه اصلی برنامه‌ریزی کند.

امتیازهای قدرت: محاسبه Wilks، DOTS و IPF GL بر اساس مجموع وزنه‌ها و وزن بدن شما، به همراه مقایسه امتیاز DOTS شما با تمام لیفترهای raw یا equipped در پایگاه داده OpenPowerlifting.

رکوردها: رکوردهای جهانی پاورلیفتینگ، قوی‌ترین مردان، قدرت پنجه (grip)، و دو و میدانی؛ همراه با نمایش رکورد شخصی شما به صورت درصدی از رکورد جهانی.

تایمر استراحت: زمانی بین ۱:۰۰ تا ۵:۰۰ دقیقه یا زمان دلخواه خود را انتخاب کنید. تایمر در طول فعالیت، صفحه نمایش را روشن نگه می‌دارد و پس از اتمام زمان، به شما هشدار می‌دهد.

همه قابلیت‌ها با lb یا kg کار می‌کنند و گزینه Share لینکی از اعداد دقیق روی صفحه را ارسال می‌کند.

این برنامه هیچ دسترسی به اینترنت ندارد، بنابراین هرگز هیچ درخواست شبکه‌ای ارسال نمی‌کند. بدون تبلیغات و بدون نیاز به حساب کاربری است و شما را ردگیری نمی‌کند. تنظیمات و چیدمان صفحه‌های شما فقط روی گوشی خودتان باقی می‌ماند.

نرم‌افزار liftmath یک نرم‌افزار آزاد تحت مجوز GPL-3.0-or-later است. این برنامه همچنین در هر مرورگری از طریق liftmath.munzzyy.dev و همین‌طور به عنوان یک کتابخانه Python و ابزار خط فرمان قابل اجراست.', description_fa_source = 'machine' WHERE package_name = 'io.github.munzzyy.liftmath' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'توضیحات: برنامه Veilleuse گوشی شما را به یک چراغ‌خواب ساده، بدون هیچ‌گونه تبلیغات و ردیاب تبدیل می‌کند.

امکانات:
* دو منبع نور: فلش دوربین، یا صفحه نمایش با رنگ گرم قابل تنظیم.
* مدت‌زمان قابل تنظیم پیش از خاموش شدن خودکار (۱ تا ۱۲۰ دقیقه).
* خاموش شدن آنی یا تدریجی (fade)، با قابلیت تنظیم مدت‌زمان محو شدن نور.
* رابط کاربری کاملاً مشکی (OLED)، جهت کاهش مصرف باتری و جلوگیری از خیرگی چشم.
* در حالت فعال، صفحه نمایش کاملاً تاریک می‌شود؛ با یک بار لمس، دکمه‌های کنترلی (زمان باقی‌مانده، دکمه Stop) دوباره ظاهر می‌شوند.
* پس از پایان تایمر، برنامه خودبه‌خود بسته می‌شود تا گوشی بتواند به‌طور عادی به حالت sleep برود.

صفحه تنظیمات:
* فرمت نمایش زمان: فشرده، با جزئیات، یا HH:MM:SS.
* رنگ اصلی UI: پالتی از رنگ‌ها و سفید، به همراه اسلایدر برای تیره‌تر کردن آن.
* زبان برنامه: ۲۶ زبان در دسترس، مستقل از زبان سیستم.

