UPDATE apps SET description_fa = 'با droidVNC-NG، یک سرور VNC قدرتمند و متن‌باز طراحی‌شده برای شبکه‌های محلی، دستگاه Android خود را به یک ایستگاه کاری کنترل‌ازراه دور تبدیل کنید. این برنامه راهکاری همه‌فن‌حریف برای دسترسی از راه دور ارائه می‌دهد.

💻 کنترل از راه دور و تعامل

• اشتراک‌گذاری صفحه‌نمایش: صفحه‌نمایش دستگاه خود را از طریق شبکه به اشتراک بگذارید، همراه با قابلیت تغییر مقیاس (scaling) اختیاری در سمت سرور برای عملکرد بهتر.
• کنترل از راه دور: از کلاینت VNC خود برای کنترل دستگاه، از جمله ورودی ماوس و کیبورد استفاده کنید. برای فعال‌سازی این ویژگی، باید AccessibilityService را برای برنامه در دستگاه خود فعال کنید.
• عملکردهای کلیدهای خاص: اجرای کلیدهای کاربردی مانند «برنامه‌های اخیر» (Recent Apps)، دکمه Home، دکمه Back، و کنترل‌های پاور و صدا از راه دور.
• کپی و پیست متن: پشتیبانی از کپی و پیست کردن متن از دستگاه شما به کلاینت VNC. توجه داشته باشید که کپی و پیست از سرور به کلاینت برای متون انتخاب‌شده در کادرهای متنی قابل ویرایش به‌صورت خودکار، یا به‌صورت دستی با به اشتراک‌گذاری متن با droidVNC-NG از طریق قابلیت Share-To در Android کار می‌کند.
• نشانگرهای ماوس متعدد: نمایش نشانگرهای ماوس متفاوت برای هر کلاینت متصل‌شده روی دستگاه شما.

🌴 قابلیت‌های رفاهی

• دسترسی از طریق مرورگر وب: کنترل مستقیم صفحه‌نمایش به اشتراک گذاشته‌شده دستگاه از طریق مرورگر وب، بدون نیاز به کلاینت VNC مجزا.
• شناسایی خودکار: برنامه droidVNC-NG از Zeroconf/Bonjour برای شناسایی آسان توسط کلاینت‌های نیتیو استفاده می‌کند.

🔐 امنیت و پیکربندی

• محافظت با رمز عبور: از اتصال VNC خود با رمز عبور محافظت کنید. توجه داشته باشید در صورتی که می‌خواهید با استفاده از برنامه داخلی Screen Sharing در MacOS به سرور دسترسی داشته باشید، تنظیم رمز عبور الزامی است.
• تنظیمات پورت سفارشی: پورت مورد استفاده سرور VNC برای اتصالات را انتخاب کنید.
• اجرا در زمان راه اندازی: شروع به کار خودکار سرویس VNC هنگام روشن شدن دستگاه. در Android 11 و جدیدتر، این قابلیت با لانچرهای kiosk-mode و حالت lock task نیز کار می‌کند.
• پیکربندی پیش‌فرض: بارگذاری پیکربندی پیش‌فرض از یک فایل JSON یا Mobile Device Management.

🚀 قابلیت‌های پیشرفته VNC

• قابلیت Reverse VNC: به دستگاه خود اجازه دهید تا بدون نیاز به باز کردن پورت‌ها روی روتر، اتصال VNC را با کلاینت برقرار کند.
• پشتیبانی از ریپیتر: اتصال به ریپیتری که از UltraVNC-style Mode-2 برای شبکه‌سازی انعطاف‌پذیرتر پشتیبانی می‌کند.

لطفاً توجه داشته باشید که قابلیت‌های بیشتری همچنان در حال اضافه شدن به droidVNC-NG هستند. لطفاً هرگونه مشکل یا درخواست ویژگی جدید را در https://github.com/bk138/droidVNC-NG گزارش دهید.', description_fa_source = 'machine' WHERE package_name = 'net.christianbeier.droidvnc_ng' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
