UPDATE apps SET description_fa = 'Clench یک کیف پول اختصاصی بیت‌کوین (Bitcoin-only) و غیرحضانتی (non-custodial) برای اندروید است. این برنامه از Bitcoin Dev Kit استفاده کرده و داده‌های کیف پول را به صورت محلی روی دستگاه ذخیره می‌کند.

قابلیت‌های کیف پول:
- ساخت کیف پول‌های single-sig (تک‌امضا) و multisig (چندامضا).
- وارد کردن کیف پول‌های watch-only از طریق descriptorها.
- ساخت یا بازیابی کیف پول‌های عبارت بازیابی BIP-39 به همراه passphrase اختیاری.
- استفاده از انواع اسکریپت‌های native SegWit، nested SegWit، legacy و Taproot.
- اتصال به سرورهای Electrum، از جمله سرورهای شخصی و مسیرهای Tor SOCKS5.
- استفاده از coin control، مسدودسازی UTXO، برچسب‌گذاری (labels)، پرداخت‌های دسته‌ای (batch payments)، افزایش کارمزد به روش RBF، روش CPFP، لغو تلاش‌های جایگزینی، وارد کردن تراکنش‌های خام (raw transaction) و فرآیندهای sweep.
- اجرای عیب‌یابی نود (node diagnostics) برای مسیر Electrum، حالت Tor، TLS pinning، نسخه سرور و ارتفاع آخرین بلاک (tip height).

قابلیت‌های کیف پول سخت‌افزاری:
- تبادل PSBTها از طریق QR انیمیشنی، BBQr، لمس عمدی NFC، وارد کردن فایل از microSD/فایل انتخابی کاربر، یا وارد کردن امضای بازگشتی در صورت پشتیبانی.
- برنامه Clench با دستگاه‌های امضاکننده از طریق USB یا Bluetooth ارتباط برقرار نمی‌کند. دستگاه امضاکننده همچنان می‌تواند از USB برای تأمین برق استفاده کند.
- سازگار با امضاکننده‌های مبتنی بر QR مانند SeedSigner، Keystone، Foundation Passport و Blockstream Jade. نسخه v0.3.28 تنظیمات پیش‌فرض پروتکل‌های تأییدنشده فیزیکی را برای OneKey Pro، Krux و Specter DIY اضافه می‌کند؛ پیش‌تنظیمات Krux و Specter DIY شامل انتقال فایل/microSD انتخابی کاربر نیز می‌شوند.
- پشتیبانی از مسیرهای انتقال Coldcard Q، Coldcard Mk4 و Coldcard Mk5.
- بررسی وضعیت پروتکل TAPSIGNER NFC Tap.
- فرآیند Sweep اسلات‌های فعال SATSCARD با تأیید گواهی (certificate) و تأیید صریح باز کردن پلمپ (unseal) با احراز هویت CVC.
- راه‌اندازی، تأیید، وارد کردن و پشتیبان‌گیری از کارت‌های TAPSIGNER، و امضای مستقیم ورودی‌های پشتیبانی‌شده تک‌امضایی BIP84 native-SegWit یا چندامضایی استاندارد BIP48 native-P2WSH به همراه بررسی کامل درون‌برنامه‌ای و تأیید امضای بازگشتی.
- امضای پرداخت TAPSIGNER از Taproot، legacy، nested SegWit، P2WSH غیراستاندارد، سایر مسیرهای حساب یا تغییر PIN پشتیبانی نمی‌کند.
- مسیرهای چندامضایی OneKey Pro، Krux، Specter DIY و TAPSIGNER دارای پوشش تست خودکار هستند اما پذیرش فیزیکی ثبت‌شده‌ای روی دستگاه واقعی ندارند؛ هیچ ادعایی درباره سازگاری مدل/فریم‌ور برای این مسیرهای جدید وجود ندارد.
- نیاز به تأیید صریح برای انتشار (broadcast) پس از امضا با کیف پول سخت‌افزاری.

قابلیت‌های امنیت و حریم خصوصی:
- رمزنگاری کلیدها با Android Keystore.
- رمزنگاری پایگاه داده برنامه (Room) با SQLCipher. فایل‌های وضعیت عمومی کیف پول BDK متکی بر ساندباکس برنامه اندروید و رمزنگاری دستگاه هستند.
- حفاظت از دسترسی به کیف پول با PIN و احراز هویت بیومتریک در صورت دسترس بودن.
- اعتبارسنجی PSBTهای امضاشده و تراکنش‌های نهایی‌شده قبل از انتشار.
- عدم استفاده از ابزارهای تحلیلی (analytics)، SDKهای تبلیغاتی، Firebase، خدمات Google Play Services، سرویس‌های گزارش خرابی (crash reporting) و ورود به حساب کاربری.

استفاده از شبکه تنها به همگام‌سازی (sync) کیف پول و استعلام اختیاری کارمزد یا قیمت به درخواست کاربر محدود شده است.

