UPDATE apps SET description_fa = 'برنامه‌های Android علاقه زیادی به باز کردن لینک‌ها در مرورگر درون‌برنامه‌ای دارند: یک پنجره کوچک و ساده داخل خود برنامه، فقط با یک صفحه، بدون تب، بدون افزونه، بدون تاریخچه و بدون اینکه بعد از بستن آن چیزی باقی بماند.

این برنامه در عوض، آن لینک‌ها را به مرورگر واقعی شما می‌فرستد.

کافی است آن را به عنوان مرورگر پیش‌فرض خود تنظیم کنید، سپس یک بار آن را باز کنید تا انتخاب کنید لینک‌ها باید به کدام‌یک از مرورگرهای نصب‌شده شما منتقل شوند. از آن به بعد، هر لینکی که یک برنامه تحویل سیستم می‌دهد، در همان مرورگری باز می‌شود که واقعاً از آن استفاده می‌کنید؛ همراه با بوکمارک‌ها، اطلاعات ورود (Logins) و مسدودکننده محتوای شما.

کل کارایی برنامه همین است. هیچ تنظیمات دیگری فراتر از همان یک انتخاب وجود ندارد. این برنامه به خودی خود هیچ دسترسی به اینترنت ندارد و شامل هیچ ابزار آماری (Analytics)، تبلیغات و ردیابی نیست. این برنامه هرگز صفحه‌ای را بارگذاری نمی‌کند: فقط لینک را منتقل می‌کند و کنار می‌کشد.

یک محدودیت که بد نیست بدانید: برخی برنامه‌ها اصلاً لینک را به سیستم تحویل نمی‌دهند و صفحه را خودشان نمایش می‌دهند. Facebook و Instagram نمونه‌های رایج آن هستند. هیچ برنامه‌ای که روی دستگاه نصب شده باشد نمی‌تواند مسیر آن‌ها را تغییر دهد، از جمله همین برنامه.

