UPDATE apps SET description_fa = 'دستگاه اندرویدی خود را با Sensagram به یک هاب سنسور پویا تبدیل کنید که امکان استریم پیوسته و آنی داده‌ها را فراهم می‌کند. Sensagram به شما اجازه می‌دهد داده‌های زنده سنسور را به‌صورت یکپارچه روی UDP استریم کرده و از تاخیر بسیار پایین آن اطمینان حاصل کنید.

طیف گسترده‌ای از سنسورهای اندروید شامل داده‌های حرکتی، موقعیتی، محیطی و GPS (مکان‌یابی) را بدون دردسر و مستقیماً به یک آدرس IP یا سرور مشخص ارسال کنید؛ ابزاری فوق‌العاده برای توسعه‌دهندگان، پژوهشگران و علاقه‌مندان به دنیای فناوری.

ویژگی‌های کلیدی:

- استریم آنی (Real-time): انتقال داده‌های سنسور در زمان واقعی برای دریافت بازخورد دقیق و فوری.
- پشتیبانی جامع از سنسورها: استریم داده‌ها از سنسورهای حرکتی (ژیروسکوپ، شتاب‌سنج)، موقعیتی (میدان مغناطیسی، بردار چرخش)، محیطی (نور، دما) و GPS (مکان‌یابی).
- تاخیر کم با UDP: تجربه سرعت و کارایی UDP با حداقل تاخیر در انتقال داده‌ها، ایده‌آل برای برنامه‌های حساس به زمان.
- آدرس‌های مقصد (Endpoints) قابل تنظیم: پیکربندی آسان و ارسال داده‌ها به آدرس IP یا Endpoint شبکه دلخواه شما.

در برنامه، سنسورهای مورد نظر را از لیست انتخاب کرده و دکمه "Stream" را لمس کنید. با این کار، ارسال داده‌های سنسور به آدرس مشخص‌شده آغاز می‌شود. برای دریافت داده‌ها، باید یک سرور UDP راه‌اندازی کنید. این برنامه داده‌ها را با فرمت JSON ارسال می‌کند.

