UPDATE apps SET description_fa = 'کیف پولی که تنها با یک نگاه وضعیتش را می‌بینید.

‏UPI Expense Tracker یک برنامه مدیریت هزینه‌های شخصی ۱۰۰٪ آفلاین برای پرداخت‌های UPI است. این برنامه به‌آرامی تمام پرداخت‌های شما را ثبت، دسته‌بندی و میزان هزینه‌های روزانه، هفتگی و ماهانه به همراه موجودی قابل استفاده را در یک نگاه — روی صفحه اصلی و ویجت‌های صفحه اصلی — نمایش می‌دهد. هیچ حسابی، هیچ ابری، هیچ تبلیغاتی و هیچ ردیابی وجود ندارد. همه چیز روی گوشی شما باقی می‌ماند.

قابلیت‌ها

* ثبت خودکار پرداخت‌ها. یک Accessibility Service تاییدیه پرداخت روی صفحه را از برنامه UPI شما (Google Pay، PhonePe، Paytm، CRED) و SMS پرداخت بانک می‌خواند، سپس مبلغ، دریافت‌کننده و زمان را ثبت می‌کند. موارد تکراری بر اساس شماره مرجع بانک حذف می‌شوند.
* نمایش هزینه‌ها. مجموع هزینه‌های این هفته و این ماه، نمودار هزینه، تراکنش‌های اخیر و دسته‌بندی‌های خودکار مانند غذا، خواربار، حمل‌ونقل و قبوض.
* کیف پول موجودی قابل استفاده. یک مقدار پایه دستی منهای هزینه‌های ثبت‌شده، که می‌توانید هر زمان آن را با رقم واقعی دوباره همگام‌سازی کنید.
* ویجت‌های صفحه اصلی برای هزینه، موجودی قابل استفاده، بودجه ماهانه و روند پیشرفت بودجه هفتگی/ماهانه.
* اطلاع‌رسانی هنگام توقف ثبت. اگر کلید دسترسی (Accessibility) خاموش شود، یک یادآوری دریافت می‌کنید و ویجت‌ها عبارت «Capture paused» را نشان می‌دهند تا مجموع هزینه‌های متوقف‌شده هرگز به‌روز به نظر نرسد.
* بودجه‌بندی. سقف ماهانه تعیین کنید و پر شدن آن را روی کارت صفحه اصلی و ویجت تماشا کنید.

حریم خصوصی — هیچ اطلاعاتی از گوشی شما خارج نمی‌شود

دسترسی INTERNET به‌طور کامل از برنامه حذف شده است، بنابراین قادر به ارسال هیچ داده‌ای به خارج از دستگاه نیست. هیچ پردازش ابری، ابزار تحلیلی، گزارش خرابی (Crash reporting) و ردیابی شخص ثالث وجود ندارد؛ داده‌های شما فقط در یک پایگاه داده محلی ذخیره می‌شوند. خروجی CSV کاملاً محلی است و توسط خود شما به صورت دستی به اشتراک گذاشته می‌شود. دکمه حمایت مالی صرفاً یک صفحه پرداخت را در مرورگر شما باز می‌کند — هیچ SDK پرداختی درون برنامه وجود ندارد.

دسترسی‌ها

* دسترسی Accessibility Service — صفحه تایید پرداخت برنامه UPI را برای ثبت پرداخت می‌خواند. برای ثبت خودکار ضروری است؛ البته می‌توانید پرداخت‌ها را به صورت دستی هم اضافه کنید.
* دسترسی Receive SMS — پیامک‌های دریافتی پرداخت بانکی را برای دریافت شماره مرجع و واریزی‌ها می‌خواند. این تنها یک انتشار دریافتی (Delivery broadcast) است و صندوق پیامک‌های موجود شما را نمی‌خواند.
* موقعیت مکانی (Fine/Coarse) — اختیاری است، صرفاً برای سنجاق کردن محل انجام پرداخت روی نقشه Insights. هیچ دسترسی موقعیت مکانی در پس‌زمینه وجود ندارد.
* ارسال اعلان‌ها (Post notifications) — یادآوری هنگام خاموش شدن ثبت پرداخت، به همراه هشدارهای اختیاری بودجه.
* نادیده گرفتن بهینه‌سازی باتری (Ignore battery optimizations) — اختیاری است، تا سرویس ثبت پرداخت در پس‌زمینه بسته نشود.

این یک برنامه تک‌کاربره است که برای خودتان نصب می‌کنید. از آنجا که این برنامه صفحات پرداخت و SMS را می‌خواند، اجازه حضور در Google Play Store را ندارد و تنها از طریق کانال‌های متن‌باز توزیع می‌شود.

