مدیریت آسان کلیدها
در چند ثانیه جفت‌کلیدهای قوی PGP بسازید. ترکیب مدرن Ed25519 (امضا) + X25519 (رمزنگاری) را برای کلیدهای سریع، کوتاه و امن انتخاب کنید، یا از کلیدهای کلاسیک RSA تا ۴۰۹۶ بیت برای حداکثر سازگاری استفاده کنید. همه کلیدهای خود را در یک جا مدیریت کنید: مشاهده، فهرست کردن، وارد کردن (import) و صادر کردن (export) کلیدهای عمومی و خصوصی با قالب ASCII-armored.

رمزنگاری و رمزگشایی پیام‌ها
هر متنی را با کلید عمومی دریافت‌کننده رمزنگاری کنید تا فقط خود او — با استفاده از کلید خصوصی‌اش — بتواند آن را بخواند. پیام‌های دریافتی را با کلید خصوصی خودتان که توسط passphrase حفاظت شده است، رمزگشایی کنید. رمزنگاری متن از AES-256 همراه با یک session key جدید استفاده می‌کند و هر پیام دارای بررسی یکپارچگی (integrity check) است.

امضا و اعتبارسنجی
با امضا کردن متن توسط کلید خصوصی خود، اصالت پیام را اثبات کرده و از دستکاری آن جلوگیری کنید. امضاها را با کلید عمومی مربوطه اعتبارسنجی کنید تا مطمئن شوید پیام واقعاً از طرف فرستنده آن ارسال شده است.

کاملاً آفلاین و خصوصی
تمام عملیات رمزنگاری به‌صورت محلی و با استفاده از کتابخانه متن‌باز Bouncy Castle انجام می‌شود. کلیدهای خصوصی شما به‌صورت رمزنگاری‌شده با AES-256 در فضای ذخیره‌سازی اختصاصی برنامه نگهداری می‌شوند و passphrase شما هرگز ذخیره نمی‌شود. این برنامه هیچ دسترسی (permission) خاصی درخواست نمی‌کند و هیچ ارتباط شبکه‌ای برقرار نمی‌سازد — اطلاعات محرمانه شما هرگز از گوشیتان خارج نمی‌شوند.

زیبا و کاربرپسند
رابط کاربری مدرن Material 3 با تم‌های روشن و تاریک و پشتیبانی از Dynamic Color در Android 12 به بالا. فیلدهای متن، کادرهای گفتگو (dialogs) و تمامی بخش‌ها به‌گونه‌ای ساده و روان طراحی شده‌اند. همچنین کل برنامه به زبان‌های انگلیسی، چینی ساده‌شده، چینی سنتی، ژاپنی، کره‌ای، فرانسوی، آلمانی، اسپانیایی، پرتغالی، ایتالیایی، روسی، هلندی، لهستانی، ترکی، عربی، هندی، اندونزیایی، ویتنامی و تایلندی در دسترس است.

سازگار با F-Droid
این برنامه طبق دستورالعمل‌های سخت‌گیرانه قابلیت بازتولید (reproducibility) در F-Droid ساخته شده است، بنابراین می‌توانید با اطمینان کامل آن را نصب کرده یا از کد منبع بسازید.

