UPDATE apps SET description_fa = 'برنامه‌ی Blockstream (سابقاً Green) یک کیف پول Bitcoin ساده و امن است که ارسال و دریافت Bitcoin و دارایی‌های مبتنی بر شبکه Liquid مانند Liquid Bitcoin (L-BTC) و USDt شرکت Tether را آسان می‌کند.

این کیف پول که توسط Blockstream (یکی از امنیت‌محورترین تیم‌ها در صنعت Bitcoin) ساخته شده، در پلتفرم‌های مختلف پشتیبانی می‌شود و هم برای افراد تازه‌کار و هم برای کاربران حرفه‌ای Bitcoin طراحی شده است.

راه‌اندازی آسان
برای شروع به هیچ ثبت‌نام یا اطلاعات شخصی نیاز نیست؛ فقط عبارت بازیابی (recovery phrase) خود را یادداشت کنید و بلافاصله تراکنش‌های Bitcoin خود را آغاز نمایید.

خرید مستقیم BITCOIN به کیف پول شخصی (SELF-CUSTODY)
بدون واسطه، Bitcoin را مستقیماً در کیف پول خود خریداری کنید (ممکن است به ثبت‌نام تکمیلی نیاز باشد).

تراکنش‌های سریع‌تر و ارزان‌تر BITCOIN
تخمین هوشمند کارمزد تضمین می‌کند که پرداخت‌های Bitcoin شما به موقع و بدون پرداخت کارمزدهای اضافی انجام شوند.

چندزبانه
ما به زبان شما صحبت می‌کنیم. Green از زبان‌های پرتغالی برزیلی، چینی (ساده‌شده)، هلندی، انگلیسی، فرانسوی، آلمانی، عبری، ایتالیایی، ژاپنی، کره‌ای، روسی، اسپانیایی، اوکراینی، ویتنامی و زبان‌های بیشتری در آینده پشتیبانی می‌کند!

پشتیبانی از لایه ۲ BITCOIN
ارسال و دریافت Liquid Bitcoin L-BTC، USDt شرکت Tether و هر دارایی دیگری بر پایه شبکه Liquid با یک حساب Liquid.

کاربران حرفه‌ای Bitcoin با مجموعه گسترده‌ای از قابلیت‌های پیشرفته و نوآوری‌های بی‌نظیر، کاملاً احساس راحتی خواهند کرد:

کنترل کارمزد
کارمزدهای تراکنش کاملاً قابل سفارشی‌سازی با پشتیبانی از Replace-by-Fee تا بتوانید با کارمزد کم شروع کنید و در صورت نیاز آن را تنظیم نمایید. عالی برای پیش‌بردن تراکنش‌های فوری بدون پرداخت هزینه اضافی.

پشتیبانی از HARDWARE WALLET
ادغام با Blockstream Jade، Ledger Nano S و X، Trezor One و T (برای اطلاع از آخرین سازگاری در پلتفرم‌های مختلف پشتیبانی‌شده به بخش راهنمای ما مراجعه کنید).

آستانه تایید دو مرحله‌ای (TWO-FACTOR THRESHOLDS)
با تنظیم آستانه تایید دو مرحله‌ای، احراز هویت دو مرحله‌ای را فقط برای پرداخت‌های بزرگ الزامی کنید. مجموع پرداخت‌ها تا سقف مشخص‌شده را می‌توان بدون 2FA انجام داد.

کیف پول‌های WATCH-ONLY
موجودی Bitcoin خود را در هر جایی زیر نظر داشته باشید و بدون نیاز به اعطای مجوزهای پرداخت در دستگاه خود، از دیگران پرداخت دریافت کنید.

پشتیبانی از TESTNET
به‌راحتی تراکنش‌های آزمایشی را روی Bitcoin testnet انجام دهید تا زمانی که با نحوه کار کیف پول کاملاً آشنا شوید.

حریم خصوصی
بدون نیاز به مدارک، اطلاعات شخصی یا KYC. آدرس ایمیل فقط برای بازیابی کیف پول مورد نیاز است. تنها با لمس یک دکمه و بدون نیاز به برنامه‌های دیگر از طریق Tor متصل شوید.

اتصال به NODE اختصاصی خود
تراکنش‌ها را روی Full Node اختصاصی خود با پشتیبانی از SPV تایید کنید.', description_fa_source = 'machine' WHERE package_name = 'com.greenaddress.greenbits_android_wallet' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'GrooveForge یک استودیوی کیبورد MIDI قابل حمل برای Android است. یک MIDI controller وصل کنید، یک soundfont انتخاب کنید و بنوازید.

این برنامه در ابتدا به عنوان یک ابزار تمرینی سبک جهت استفاده روی گوشی یا تبلت برای بازسازی گام‌ها و حافظه عضلانی روی کیبورد آغاز شد. فراتر از آن رشد کرد، اما همچنان ابزاری برای تمرین و نواختن است، نه یک DAW.

تمرین‌های گروهی

یک گروه موسیقی بدون نیاز به استودیو با هم یک قطعه را تمرین می‌کنند. هر کس پارت خود را روی مترونوم (click) مشترک با گوشی خود ضبط می‌کند و پارت‌ها در یک تنظیم جمع‌آوری می‌شوند که نسخه‌ی کامل آن روی همه دستگاه‌ها ذخیره می‌شود.

یک فایل ضبط‌شده را برای هم‌نوازی وارد (Import) کنید — MP3، FLAC و WAV در همه جا، به همراه M4A، AAC و صدای ویدیو در Android. ضرب‌آهنگ (tempo) را لمس کنید، سپس مارکر را روی اولین ضرب اصلی (downbeat) بکشید تا شبکه‌بندی (grid) با موسیقی هماهنگ شود.

هر دستگاهی در مسیر خروجی و ورودی صدا کمی تاخیر ایجاد می‌کند که باعث عقب افتادن ضبط (take) می‌شود. GrooveForge این تاخیر را روی دستگاه شما اندازه‌گیری کرده و ضبط شما را به همان اندازه به عقب می‌کشد، تا آنچه دقیقاً روی ضرب نواخته‌اید، روی ضرب قرار گیرد.

هیچ چیزی جایی آپلود نمی‌شود و نیازی به ساخت حساب کاربری نیست. دستگاه‌ها مستقیماً روی شبکه محلی همگام‌سازی (sync) می‌شوند: کافی است یک بار کد را اسکن کنید و سپس باز کردن همان قطعه کافی است. به اینترنت نیازی نیست و بدون Wi-Fi نیز هات‌اسپات یک گوشی نقش کل شبکه را ایفا می‌کند.

سازها

GrooveForge Keyboard — سینتی‌سایزر soundfont با فرمت sf2. همراه با انتخاب بانک و پچ و مسیریابی کانال MIDI. هر اسلات کاملاً مستقل است.
Vocoder — سنتز صدای مبتنی بر میکروفون.
Stylophone — ساز تک‌صدایی (مونوفونیک) با نوار فلزی.
Theremin — تاچ‌پد با کنترل عمودی زیروبمی (pitch) و افقی صدا (volume).
Drum Generator — الگوهای ریتم از بوسانووا تا متال، با حس واقعی و انسانی.

Xen: گام‌های ریزپرده‌ای (Microtonal)

یک نت را نگه دارید، یک گام را لمس کنید. نتی که نگه داشته‌اید به نت پایه (tonic) تبدیل می‌شود، کیبورد روی گام ساخته‌شده روی آن قفل می‌شود و — برای گام‌هایی که تعدیل‌شده (equal-tempered) نیستند — کلیدهای مورد استفاده دوباره کوک می‌شوند تا دقیقاً طبق سنت مربوطه به گوش برسند. یک کیبورد، یک حرکت.

۹۲ گام در ۱۱ خانواده: مد‌های غربی؛ مقام‌های عربی و ترکی؛ دستگاه‌های ایرانی؛ راگاهای هندی در کوک خالص (just intonation)؛ مد‌های چینی، ژاپنی و کره‌ای؛ هفت‌بخشی برابر تایلندی؛ گاملان جاوه و بالی؛ قنت اتیوپیایی و آمادیندای اوگاندایی؛ نی‌انبان اسکاتلندی، فیدل هاردانگر و سرودهای بیزانسی؛ سیستم‌های کوک تاریخی؛ و تقسیمات برابر از ۱۳ تا ۳۱ تن، Bohlen-Pierce، و آلفا، بتا و گامای غیر اکتاوی Wendy Carlos.

تغییر کوک به جای pitch bend از جدول کامل کوک MIDI استفاده می‌کند، بنابراین هر نت از یک آکورد با فرکانس دقیق خود شنیده می‌شود. کلیدهای خارج از گام خاکستری می‌شوند و کلیدهای تغییر کوک یافته، میزان تغییر خود را به سنت (cent) نشان می‌دهند.

منشأ اعداد هر گام مشخص شده است: سیستم‌های کوک دقیق هستند، مقام‌ها از کنوانسیون‌های نت‌نویسی پیروی می‌کنند و گاملان‌ها با گوش کوک می‌شوند و از سازی به ساز دیگر متفاوت هستند.

گام‌های اختصاصی خودتان را هم بسازید — تعداد دلخواه درجات، میزان تغییر کوک برای هر کلید و قابلیت Mute برای قابل‌نواختن نگه‌داشتن یک درجه در حالی که قفل گام آن را نادیده می‌گیرد. قابلیت Import و Export فایل‌های Scala (.scl).

لوپرها

MIDI Looper — ضبط و لوپ الگوهای MIDI با همگام‌سازی میزان (bar sync).
Audio Looper — ضبط و لوپ صدای زنده با همگام‌سازی میزان، overdub و معکوس‌سازی (reverse).

افکت‌ها

Plate reverb، ping-pong delay، wah (خودکار یا کنترل با پدال)، EQ چهار بانده، کمپرسور و chorus/flanger، با قابلیت BPM sync در موارد کاربردی. ویژگی Live Input صدای میکروفون یا line-in را از درون هر یک از آن‌ها عبور می‌دهد.

سایر امکانات

Plugin rack — رک مرتب‌شده از اسلات‌های ماژول با قابلیت کشیدن و رها کردن (drag-and-drop) و تغییر چیدمان در هر زمان.
Scale lock and highlighting — رنگ‌بندی نت پایه (root)، نت‌های درون گام و خارج از گام روی کیبورد لمسی.
Jam Mode — یک اسلات نقش اصلی (lead) را دارد و اسلات‌های بعدی با هارمونی آن هماهنگ می‌شوند.
CC mapping — نگاشت (map) ولوم‌ها، اسلایدرها و پدهای سخت‌افزاری به افکت‌های MIDI یا عملکردهای برنامه.
Projects — ذخیره و بازگردانی چیدمان کامل رک در یک فایل gf. آخرین نشست (session) با هر تغییر به طور خودکار ذخیره می‌شود.

