UPDATE apps SET description_fa = 'برنامه «Mental Math» یک اپلیکیشن ساده و خلوت برای تقویت محاسبات ذهنی در اندروید است. می‌توانید به تنهایی تمرین کنید یا دوستان خود را به رقابت دعوت کرده و مهارت‌هایتان را ارتقا دهید. این برنامه متن‌باز است و به حریم خصوصی شما احترام می‌گذارد.

تمرین‌های قابل شخصی‌سازی
عملگرهای ریاضی مورد نظر خود را برای تمرین انتخاب کنید (+، −، ×، ÷). برای هر عملگر، از میان نه سطح دشواری انتخاب کنید تا تمرین‌ها دقیقاً با سطح مهارت شما هماهنگ شوند.

دو حالت بازی
• حالت تمرینی (Practice Mode): به شما امکان می‌دهد تعداد مشخصی مسئله (۱۰، ۲۰، ۳۰، ۴۰ یا ۵۰) را حل کنید.
• حالت زمانی (Timed Mode): شما را به چالش می‌کشد تا در یک بازه زمانی مشخص (۱، ۲، ۳، ۴ یا ۵ دقیقه) به بیشترین تعداد مسئله ممکن پاسخ دهید.

دوستان خود را به چالش بکشید
می‌توانید لینک بازی را به اشتراک بگذارید تا:
۱. یک بازی تمام‌شده را با همان مسائل دقیقاً دوباره بازی کنید تا امتیازات خود را با دوستانتان مقایسه نمایید.
۲. یک بازی جدید با تنظیمات از پیش‌تعیین‌شده شروع کنید تا یک چالش عادلانه و تازه برای همه ایجاد شود.

محاسبه سطح دشواری
دشواری مسائل با استفاده از الگوریتم‌هایی مبتنی بر جمع ستونی، تفریق ستونی، ضرب چندرقمی و تقسیم چندرقمی تعیین می‌شود تا تمرین‌هایی واقعی و متوازن ایجاد گردد.

نتایج دقیق و با جزئیات
پس از هر بازی، خلاصه‌ای دقیق شامل تنظیمات انتخابی، عملکرد شما (دقت، سرعت و امتیاز) و لیست کاملی از تمام مسائل و پاسخ‌هایتان را برای بررسی مشاهده کنید.

جدول امتیازات شخصی
۱۰ نتیجه برتر شما به تفکیک هر ترکیب از تنظیمات نمایش داده می‌شوند تا بتوانید به راحتی پیشرفت خود را پیگیری کنید. همچنین می‌توانید خلاصه‌ای دقیق از بهترین بازی‌های خود را در هر زمان مرور کنید.

تاریخچه بازی‌ها
تاریخچه کامل تمام بازی‌های امتیازدار خود را مرور کنید. می‌توانید لیست را بر اساس زمان یا به صورت عددی مرتب کنید تا بازی‌های خاصی را پیدا کنید. در هر زمان می‌توانید هر مسابقه را دوباره بررسی کرده و خلاصه دقیق نتایج آن را ببینید.

یادآورهای تمرین
برای حفظ نظم در تمرینات ریاضی ذهنی، یادآورهای دوره‌ای تنظیم کنید. اعلانات در عصر (حدود ساعت ۶ عصر) ارسال می‌شوند و می‌توان آن‌ها را به صورت روزانه، هر سه روز یک‌بار یا هفتگی زمان‌بندی کرد.

رابط کاربری قابل شخصی‌سازی
صفحه‌کلید دلخواه خود (عددی یا مدل تلفنی) را انتخاب کنید، مسائل ریاضی را به صورت افقی یا عمودی نمایش دهید و جهت ورود اطلاعات (چپ به راست یا راست به چپ) را مطابق با سلیقه خود تنظیم کنید.

صدا و ویبره
صدا و/یا ویبره را به عنوان بازخورد در طول بازی انتخاب کنید تا بازخوردی شفاف‌تر و سریع‌تر داشته باشید. هر دو گزینه به طور مستقل قابل فعال یا غیرفعال‌سازی هستند. عملکرد ویبره ممکن است به دستگاه یا تنظیمات سیستم شما بستگی داشته باشد.

طراحی خلوت و ساده
طراحی ساده و مینیمال برنامه بدون عناصر اضافی یا حواس‌پرت‌کننده، به شما کمک می‌کند تا تمام تمرکز خود را روی تمرین محاسبات ذهنی بگذارید. از هر دو حالت روشن (Light) و تاریک (Dark) پشتیبانی می‌کند.

متن‌باز، حامی حریم خصوصی، رایگان و بدون تبلیغات
