ترازوهای Bluetooth

برنامه openScale به صورت داخلی از چندین ترازوی Bluetooth (BLE یا «هوشمند») از تولیدکنندگان مختلف مانند Beurer، Sanitas، Yunmai، Xiaomi و غیره پشتیبانی می‌کند (لیست مدل‌ها را در ادامه ببینید). ما همراه با کاربران خود، پیوسته مجموعه ترازوهای پشتیبانی‌شده را بهبود داده و گسترش می‌دهیم و در بسیاری از موارد، کاستی‌های اپلیکیشن اصلی ترازو را جبران می‌کنیم.

برای ترازوهای بدون Bluetooth، یا ترازوهای Bluetooth که (هنوز) توسط openScale پشتیبانی نمی‌شوند، می‌توانید اندازه‌گیری‌ها را به روشی سریع و آسان به صورت دستی وارد کنید.

حریم خصوصی

این اپلیکیشن هیچ تبلیغاتی ندارد و هیچ مجوز غیرضروری درخواست نمی‌کند. دسترسی به موقعیت مکانی (Location) تنها برای پیدا کردن ترازوهای Bluetooth نیاز است. پس از پیدا شدن ترازو، می‌توانید این مجوز را لغو کنید (یا اگر از Bluetooth استفاده نمی‌کنید، هرگز آن را تأیید نکنید).

شاخص‌های پشتیبانی‌شده

وزن، BMI (شاخص توده بدنی)، آب بدن، ماهیچه، LBM (توده عضلانی بدون چربی)، چربی بدن، توده استخوانی، دور کمر، نسبت دور کمر به قد، دور باسن، نسبت دور کمر به باسن، چربی احشایی، دور سینه، دور ران، دور بازو، دور گردن، کالیپر چربی بدن و BMR (نرخ سوخت‌وساز پایه). همچنین برای هر ورودی می‌توانید یک یادداشت اختیاری اضافه کنید.

نکته: اگر فکر می‌کنید این لیست خیلی طولانی است نگران نباشید: شاخص‌هایی که استفاده نمی‌کنید قابل غیرفعال‌سازی و پنهان‌کردن هستند.

سایر ویژگی‌ها

* ویجت قابل تغییر سایز برای نمایش آخرین اندازه‌گیری در صفحه اصلی
* تنظیم واحد وزن: kg، lb یا st
* امکان تعیین هدف برای کمک به حفظ رژیم غذایی
* نمایش تمام داده‌ها روی نمودار و در جدول برای پیگیری پیشرفت شما
* ارزیابی اندازه‌گیری‌ها و ارائه بازخورد بصری سریع برای نمایش این‌که آیا بر اساس سن، جنسیت، قد و غیره در محدوده پیشنهادی قرار دارید یا خیر
* وارد کردن یا خروجی گرفتن از داده‌ها به/از فایل CSV
* پشتیبانی از برآورد چربی بدن، آب بدن و توده بدون چربی بر اساس مقالات علمی؛ کاربردی برای زمانی که ترازوی شما از این اندازه‌گیری‌ها پشتیبانی نمی‌کند.
* پشتیبانی از چند کاربر
* ترجمه‌شده (به‌طور کامل یا جزئی) به زبان‌های کاتالان، چینی (سنتی)، چکی، هلندی، انگلیسی، فرانسوی، گالیسی، آلمانی، یونانی، ایتالیایی، ژاپنی، نروژی بوکمل، لهستانی، پرتغالی (برزیل)، رومانیایی، اسلواکی، اسپانیایی، سوئدی و ترکی
* تم تاریک اختیاری

