میکسر صدا
دوازده صدا، هم‌زمان تا سه صدا، هرکدام با سطح ولوم اختصاصی خود. صدای باران روی یک کافه در دوردست. شومینه همراه با باد. اقیانوس با جیرجیرک‌ها در غروب. تعادل هر ترکیب دست شماست و Ambio آن را برای دفعه بعد به خاطر می‌سپارد.

- باران، شومینه، کافه، جنگل
- پرندگان، جیرجیرک‌ها، اقیانوس، جویبار
- غار، باد، نویز سفید (White Noise)، نویز قهوه‌ای (Brown Noise)

ظاهری شبیه به صدایش
پس‌زمینه یک گرادیانت پویاست که از ترکیب تمام صداهای میکس شما ساخته شده — آبی‌های خنک برای باران، کهربایی گرم برای شومینه، سبز تیره برای جنگل. ذرات معلق در پشت تایمر شناور می‌شوند و به کل ترکیب پاسخ می‌دهند، نه فقط یک صدا. سکون را ترجیح می‌دهید؟ جلوه‌ها را خاموش کنید.

تایمر تمرکز
پیش‌فرض‌های تکنیک Pomodoro در ۲۵ یا ۵۰ دقیقه، یا تنظیم مدت زمان تمرکز و استراحت به دلخواه خودتان. یک زنگ ملایم، جلسه کاری را بدون اینکه تمرکزتان را برهم بزند پایان می‌دهد. ساخته‌شده برای درس خواندن، نوشتن، برنامه‌نویسی یا هر کاری که نیاز به توجه مداوم دارد.

برنامه‌های جلسه
به بیش از یک دور نیاز دارید؟ قابلیت Plan به شما اجازه می‌دهد مراحل تمرکز و استراحت را به هر ترتیبی پشت سر هم بچینید، آن‌ها را تکرار کنید یا همان‌جا تمام کنید. زنگ موفقیت، پایان برنامه را اعلام می‌کند.

ترکیبی برای زمان‌های استراحت
با صدایی متفاوت استراحت کنید. صدا را هنگام استراحت فعال کنید و میکس دومی را انتخاب کنید که فقط هنگام استراحت شما پخش می‌شود — با پایان استراحت، ترکیب تمرکز دوباره بازمی‌گردد.

حالت محیطی (AMBIENT MODE)
قصد زمان‌گیری ندارید؟ به حالت ambient بروید و بگذارید ترکیبتان پخش شود. برای مطالعه، مدیتیشن، آرامش یافتن یا خوابیدن — تایمر خواب پس از به خواب رفتن شما، پخش صدا را متوقف می‌کند.

بررسی زمان‌های تمرکز
تاریخچه جلسات، ساعت‌هایی را که واقعاً وقت گذاشته‌اید ثبت و پیگیری می‌کند.

طراحی‌شده برای هر صفحه‌نمایش
در تبلت‌ها، میکسر به‌طور دائمی در کنار تایمر قرار می‌گیرد — دو پنل کنار هم، بدون نیاز به جابه‌جایی مدام.

HELLO, HOLA, BONJOUR, سلام، こんにちは
برنامه Ambio حالا به زبان شما صحبت می‌کند — تمام برنامه، نه فقط این صفحه. در Android 13 به بالا می‌توانید زبان برنامه را مستقل از زبان کلی گوشی تنظیم کنید.

اولویت با حریم خصوصی
برنامه Ambio به زمان و داده‌های شما احترام می‌گذارد:
- کاملاً آفلاین کار می‌کند
- بدون نیاز به ساخت حساب کاربری
- بدون هیچ‌گونه تبلیغات، برای همیشه
- بدون ردیابی یا ابزارهای تحلیلی
- هیچ داده‌ای از دستگاه شما خارج نمی‌شود
- متن‌باز (تحت مجوز MIT License)

پخش در پس‌زمینه
جلسه کاری را شروع کنید و گوشی را کنار بگذارید. Ambio با کنترل‌های کامل رسانه به پخش ادامه می‌دهد — توقف، ادامه یا قطع صدا از پنل اعلان‌ها، صفحه قفل یا کاشی Quick Settings.

