- مصرف بهینه باتری
- حجم کم برنامه

AMBIO برای چه کسانی است؟
- دانش‌آموزان و دانشجویانی که برای امتحانات آماده می‌شوند
- دورکارانی که به تمرکز نیاز دارند
- نویسندگانی که با عوامل حواس‌پرتی می‌جنگند
