Todosian فایل‌های .md موجود شما را مستقیماً می‌خواند و ویرایش می‌کند. هیچ نیازی به وارد کردن دیتابیس، ساخت حساب کاربری یا همگام‌سازی داخلی وجود ندارد.

نحوه کارکرد

- اتصال یک پوشه با استفاده از Storage Access Framework (SAF) در Android
- هر فایل Markdown به یک دسته‌بندی تبدیل می‌شود
- کارهای روزانه از چک‌باکس‌های استاندارد Markdown استفاده می‌کنند: - [ ] و - [x]

قابلیت‌ها

