UPDATE apps SET description_fa = 'برنامه !Drink Water یک اپلیکیشن ساده برای ثبت میزان آب مصرفی روزانه و دریافت یادآوری در طول روز است؛ بدون نیاز به حساب کاربری، بدون تبلیغات و بدون ارسال هیچ اطلاعاتی از گوشی شما.

صفحه اصلی برای سرعت بالا طراحی شده است: تنها با یک ضربه، مقدار دفعه قبلی ثبت می‌شود. اگر امروز مقدار دیگری مد نظرتان است، می‌توانید بین اندازه‌های تنظیم‌شده جابه‌جا شوید یا با گزینه‌ی «مقدار دیگر…» مقدار دلخواه را وارد کنید. یک حلقه پیشرفت، میزان آب نوشیده‌شده را در مقایسه با هدف شما نشان می‌دهد و در زیر آن، لیست ثبت‌های امروز را مشاهده می‌کنید که در صورت بروز اشتباه می‌توانید آن‌ها را حذف کنید.

یادآوری‌ها به‌طور مساوی بین زمان شروع و پایانی که مشخص می‌کنید پخش می‌شوند و تعداد آن‌ها به انتخاب خودتان است. این یادآوری‌ها پس از رسیدن به هدف متوقف می‌شوند، با هر بار ثبت آب دوباره محاسبه می‌گردند و صفحه اصلی زمان یادآوری بعدی را نشان می‌دهد. یادآوری‌ها بدون صدا و فقط با ویبره فعال می‌شوند، بنابراین گوشی شما می‌تواند در حالت باصدا بماند بدون اینکه مزاحمتی ایجاد کند؛ اگر از ساعت هوشمند متصل استفاده می‌کنید، هشدار روی آن نیز دریافت می‌شود. همچنین در صورت تمایل می‌توانید گزینه‌ی رد کردن یادآوریِ بلافاصله بعد از نوشیدن آب را فعال کنید.

از طریق خود اعلان (Notification) می‌توانید مقدار همیشگی را ثبت کنید یا هشدار را برای ۱۵ دقیقه به تعویق بیندازید (Snooze). همچنین دو ویجت صفحه اصلی وجود دارد: یک ویجت 1x1 و یک ویجت 2x1 که پیشرفت امروز را نیز نشان می‌دهد. تنها با یک ضربه روی ویجت، بدون نیاز به باز کردن برنامه، مقدار همیشگی ثبت می‌شود.

در پایان روز می‌توانید یک اعلان خلاصه (به‌طور پیش‌فرض ساعت ۲۳:۰۰، با قابلیت تغییر زمان یا غیرفعال‌سازی) دریافت کنید که میزان آب نوشیده‌شده را در مقایسه با هدفتان نشان می‌دهد. همچنین با لمس هر روز در تاریخچه، صفحه جزئیات ورودی‌های آن روز باز می‌شود که می‌توانید هر کدام را خواستید حذف کنید.

تاریخچه، ۳۰ روز گذشته را همراه با مجموع روزانه، میانگین، بهترین روز و تسلسل روزانه (Streak) شما پوشش می‌دهد. می‌توانید زبان برنامه (خودکار، اسپانیایی یا انگلیسی) و تم (خودکار، روشن یا تاریک) را انتخاب کنید، تغییرات هر نسخه را درون برنامه بخوانید و از بخش تنظیمات به سازنده برنامه ایمیل بزنید.

حریم خصوصی شما: هیچ حساب کاربری، فضای ابری، تبلیغات یا ردیابی وجود ندارد. اطلاعات و تنظیمات شما فقط روی دستگاه خودتان ذخیره می‌شود. کد برنامه Open Source و تحت مجوز MIT است.

ویژگی‌های اصلی:

- ثبت آب مصرفی تنها با یک ضربه، با آخرین مقدار استفاده‌شده.
- اندازه‌های قابل تنظیم و امکان ثبت مقدار دلخواه.
- حلقه پیشرفت روزانه و لیست ثبت‌های امروز.
- پخش یادآوری‌ها در بازه زمانی انتخابی شما با تعداد هشدارهای دلخواه.
- هشدارهای ویبره‌ای بدون صدا، قابل دریافت روی ساعت هوشمند متصل.
- امکان رد کردن یادآوریِ بلافاصله بعد از نوشیدن آب.
- اقدام سریع از طریق اعلان: ثبت مقدار یا به تعویق انداختن ۱۵ دقیقه‌ای.
- ویجت‌های صفحه اصلی 1x1 و 2x1 (دومی همراه با پیشرفت امروز) برای ثبت با یک ضربه.
- اعلان خلاصه پایان روز در زمان انتخابی شما.
- تاریخچه ۳۰ روزه همراه با میانگین، بهترین روز و تسلسل روزها، به همراه صفحه جزئیات برای هر روز.
- زبان‌های خودکار، اسپانیایی یا انگلیسی؛ تم‌های خودکار، روشن یا تاریک.
- بدون حساب کاربری، بدون تبلیغات و بدون ردیابی: اطلاعات شما هرگز از دستگاهتان خارج نمی‌شود.', description_fa_source = 'machine' WHERE package_name = 'com.jjrapps.bebeagua' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'Sleep Noise برای کمک به خواب شما و پوشش دادن صدای محیط اطراف در زمانی که نمی‌توانید آنجا را ترک کنید، نویز تولید می‌کند. کافی است آن را باز کنید تا پخش شود — نیازی به فشردن هیچ دکمه‌ای نیست.

چهار صدا، نه بیشتر. نه کاتالوگی برای اسکرول کردن وجود دارد و نه نیازی به تنظیم ترکیب‌های مختلف در ساعت دو بامداد: هر کدام کار متفاوتی انجام می‌دهند.

• Masking، صدایی که برنامه با آن شروع می‌شود. شکل آن برای پوشش دادن مکالمات طراحی شده است: ۷۱٪ از انرژی خود را در بازه‌ای قرار می‌دهد که صدای گفتار در آن است، در حالی که این رقم برای نویز brown تنها ۹٪ است. این همان صدایی است که وقتی با هدفون در یک اتاق شلوغ هستید به آن نیاز دارید.
• Pink، صدای متوازن. صدایی که حس شنوایی آن را طبیعی‌ترین صدا می‌داند، زیرا انرژی را به طور مساوی در تمام اکتاوها پخش می‌کند.
• White، یکنواخت در سراسر طیف. مناسب برای پوشش دادن صداهای تیز و ناگهانی.
• Brown، عمیق و فراگیر، نزدیک به صدای باران از دور یا صدای دریا در پس‌زمینه. راحت‌ترین صدا برای خوابیدن و کم‌اثرترین گزینه برای پوشش دادن مکالمات.

این نویز یک فایل ضبط‌شده نیست: همزمان با گوش دادن شما، نمونه به نمونه روی گوشی‌تان تولید می‌شود. این یعنی هیچ loop تکرارشونده‌ای وجود ندارد که بعد از مدتی متوجه آن شوید، و از کیفیت فلزی و مصنوعی حاصل از فشرده‌سازی فایل‌های صوتی هم خبری نیست. شفافیت صدا در ساعت هشتم دقیقاً مثل ساعت اول است.

تایمر خواب هر زمان که بخواهید صدا را قطع می‌کند: ۵ دقیقه ۵ دقیقه تا نیم ساعت، ۱۰ دقیقه ۱۰ دقیقه تا یک ساعت، و سپس ۹۰ یا ۱۲۰ دقیقه. در پایان، صدا به جای قطع شدن ناگهانی، در طول دقیقه آخر به آرامی fade می‌شود؛ چرا که قطع ناگهانی صدا می‌تواند کسی را که تازه به خواب رفته بیدار کند.

می‌توانید بدون باز کردن برنامه آن را کنترل کنید: notification به شما امکان می‌دهد پخش را متوقف کنید، صدا را تغییر دهید و ۱۰ دقیقه به تایمر اضافه کنید؛ دکمه هدفون شما هم کار می‌کند. برنامه را ببندید و گوشی را رو به پایین بگذارید — پخش صدا همچنان ادامه می‌یابد.

این برنامه حتی صداهایی را که خود گوشی تولید می‌کند هم پوشش می‌دهد: هنگام پخش صدا، حالت Do Not Disturb را برای شما روشن می‌کند و با متوقف شدن صدا، دوباره آن را خاموش می‌سازد. آلارم‌ها همچنان فعال می‌مانند، زیرا استثنائاتی که قبلاً تنظیم کرده‌اید حفظ می‌شوند. Android تاکید دارد که این مجوز باید به صورت دستی داده شود، بنابراین برنامه یک بار آن را توضیح داده و شما را به صفحه مربوطه می‌برد؛ اگر ترجیح می‌دهید برنامه کاری به گوشی شما نداشته باشد، می‌توانید آن را در Settings خاموش کنید.

و وقتی دکمه pause را فشار می‌دهید، همه چیز تمام می‌شود: notification پاک می‌شود و هیچ چیزی در پس‌زمینه باقی نمی‌ماند. گوش دادن مجدد یعنی باز کردن برنامه، که در هر صورت قصد انجامش را داشتید.

رابط کاربری همیشه تاریک است. هیچ light mode یا حالت روشنی وجود ندارد و این یک فراموشی نیست: این برنامه در تخت‌خواب و با چراغ‌های خاموش استفاده می‌شود و یک صفحه سفید در آن شرایط کورکننده است.

بدون حساب کاربری، بدون پردازش ابری، بدون تبلیغات و بدون ردیابی. برنامه هرگز از اینترنت استفاده نمی‌کند: حتی مجوز اتصال به اینترنت را هم درخواست نمی‌کند، بنابراین اگر هم بخواهد نمی‌تواند این کار را انجام دهد.

آنچه دریافت می‌کنید:

• چهار نویز تولیدشده روی دستگاه شما: masking، pink، white و brown.
• پخش خودکار به محض باز کردن برنامه، با آخرین صدایی که گوش می‌دادید.
• تایمر خواب با fade شدن تدریجی صدا و دکمه‌ای برای افزودن ۱۰ دقیقه.
• فعال‌سازی اختیاری حالت Do Not Disturb هنگام پخش، بدون دست زدن به آلارم‌ها.
• امکان کنترل از notification و هدفون؛ متوقف کردن صدا باعث پاک شدن notification می‌شود.
• دارای میزان صدای مستقل از صدای media سیستم.
• ادامه پخش با صفحه خاموش و برنامه بسته.
• زبان‌های انگلیسی و اسپانیایی.
• بدون اینترنت، بدون حساب کاربری، بدون تبلیغات و بدون ردیابی.', description_fa_source = 'machine' WHERE package_name = 'com.jjrapps.sleepnoise' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
