UPDATE apps SET description_fa = 'GeoJoystick یک جوی‌استیک متن‌باز Android برای موقعیت مکانی مجازی (mock-location) جهت تست در شبیه‌ساز و تست‌های توسعه‌دهندگان است.

این برنامه از فرآیند استاندارد ارائه‌دهنده mock-location در Android استفاده می‌کند و یک پنجره شناور (floating overlay) کوچک برای جابه‌جایی موقعیت مکانی مجازی ارائه می‌دهد، بدون اینکه نیاز باشد مداوماً به برنامه اصلی بازگردید. این برنامه تلاشی برای پنهان کردن یا دور زدن وضعیت mock-location در Android نمی‌کند.

قابلیت‌ها شامل ورود دستی مختصات، انتخاب‌گر مبتنی بر OpenStreetMap، وارد کردن مختصات از لینک نقشه، حالت‌های فشرده و گسترش‌یافته پنجره شناور، مکان‌های مورد علاقه، پیش‌تنظیم‌های سرعت، سرعت سفارشی، تم‌های روشن و تاریک، و پشتیبانی از زبان‌های انگلیسی و آلمانی است.

