UPDATE apps SET description_fa = 'فراتر از دسترسی اینترنت را با Trail Sense کاوش کنید.

    طراحی شده برای کوهنوردی، بک‌پکینگ (کوله‌گردی)، کمپینگ و ژئوکشینگ
    علامت‌گذاری نقاط (Beacons) و مسیریابی به سمت آن‌ها
    استفاده به‌عنوان قطب‌نما (تنها روی دستگاه‌های دارای سنسور قطب‌نما در دسترس است)
    دنبال کردن مسیرها
    بازگشت از همان مسیر طی‌شده با قابلیت backtrack
    استفاده از عکس به‌عنوان نقشه
    برنامه‌ریزی برای وسایل مورد نیاز
    دریافت هشدار پیش از غروب آفتاب
    پیش‌بینی وضعیت آب‌وهوا (تنها روی دستگاه‌های دارای سنسور بارومتر در دسترس است)
    استفاده از گوشی به‌عنوان چراغ‌قوه
    و امکانات بسیار دیگر!

برنامه Trail Sense یک ابزار است و دقیقاً مانند هر ابزار دیگری که با خود به طبیعت می‌برید، همراه داشتن تجهیزات پشتیبان و داشتن مهارت‌های لازم ضروری است.
این برنامه صرفاً برای اهداف اطلاع‌رسانی طراحی شده است و دقت پیش‌بینی‌ها و سنسورها به عوامل مختلفی از جمله کالیبراسیون، کیفیت سنسور، منابع خارجی و غیره بستگی دارد.
مسئولیت استفاده از برنامه بر عهده خودتان است؛ همیشه ابزارهای پشتیبان (مانند قطب‌نما) همراه داشته باشید و ایمن بمانید.

همچنین این برنامه به هیچ عنوان از اینترنت استفاده نمی‌کند و هرگز استفاده نخواهد کرد - تمامی اطلاعات موجود در Trail Sense مستقیماً از سنسورهای گوشی شما دریافت می‌شوند و هیچ داده‌ای از Trail Sense خارج نخواهد شد.

مشکلات رایج

    عدم وجود قطب‌نما: اگر گوشی شما سنسور قطب‌نما ندارد، کاری از دست من برای فعال‌سازی آن ساخته نیست، چرا که این یک قابلیت سخت‌افزاری است.
    با این حال، همچنان می‌توانید از سایر امکانات Trail Sense استفاده کنید.
    عدم وجود آب‌وهوا: ابزار آب‌وهوا تنها در صورتی در دسترس است که گوشی شما دارای سنسور بارومتر (فشارسنج) باشد.

مشکلی پیدا کرده‌اید یا قابلیت جدیدی می‌خواهید؟ از طریق ایمیل trailsense@protonmail.com با من در ارتباط باشید یا یک issue جدید در GitHub ایجاد کنید: github.com/kylecorry31/Trail-Sense

من تنها توسعه‌دهنده Trail Sense هستم، بنابراین تمام تلاش خود را برای حل مشکلات انجام خواهم داد - اما دستگاه‌های محدودی برای تست در اختیار دارم.

مجوزها

    Notifications: به Trail Sense اجازه می‌دهد اعلان‌ها را نمایش دهد (backtrack، آب‌وهوا، هشدارهای غروب آفتاب، رویدادهای نجومی، تایمر جوش آمدن آب و غیره)
    Location: به Trail Sense اجازه می‌دهد موقعیت مکانی شما را برای مسیریابی، آب‌وهوا (کالیبراسیون سطح دریا) و نجوم دریافت کند.
    Background location: به Trail Sense اجازه می‌دهد موقعیت شما را در پس‌زمینه برای هشدارهای غروب آفتاب دریافت کند.
    در برخی دستگاه‌ها، این کار باعث بهبود قابلیت اطمینان backtrack و پایش آب‌وهوا نیز می‌شود.
    Physical activity: به Trail Sense اجازه می‌دهد از قدم‌شمار گوشی شما برای محاسبه مسافت استفاده کند.
    Camera: به Trail Sense اجازه می‌دهد از دوربین شما در قطب‌نمای دیده‌بانی، شیب‌سنج (clinometer) و ثبت عکس برای استفاده در Cloud Scanner، اسکنر QR Code و نقشه‌های تصویری استفاده کند.
    Alarms & reminders: به Trail Sense اجازه می‌دهد در زمان دقیق یک اعلان ارسال کند.
    این قابلیت توسط ابزار Clock (هنگام به‌روزرسانی زمان سیستم) و هشدارهای طلوع و غروب آفتاب استفاده می‌شود.

لینک‌ها

    سیاست حریم خصوصی: https://kylecorry.com/Trail-Sense/#privacy
    سوالات متداول (FAQ): https://github.com/kylecorry31/Trail-Sense#faq
