تصویرسازی‌های زیبا
صحنه‌ها شبیه کتاب‌های قصه نقاشی‌شده با دست هستند: گرم، آرامش‌بخش و پر از جذابیت.

کاملاً قابل استفاده به‌صورت آفلاین و بدون حواس‌پرتی - فقط موسیقی، بازی و شادی.

عالی برای کودکان پیش‌دبستانی، والدینی که می‌خواهند به یادگیری اولیه موسیقی فرزندشان کمک کنند، و مربیانی که می‌خواهند کودکان را با دنیای آواها آشنا کنند.', description_fa_source = 'machine' WHERE package_name = 'com.lalumo.app' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'Lplanner یک برنامه‌ریز برداشت فشار (decompression planner) برای غواصان آموزش‌دیده گازهای مخلوط (mixed-gas) است. این برنامه غواصی‌های مدار باز و مدار بسته را با هوا، nitrox، trimix و heliox برنامه‌ریزی می‌کند و امکان انتخاب از میان سه مدل برداشت فشار را فراهم می‌سازد.

این نرم‌افزار می‌تواند باعث مرگ شما شود. این برنامه آزمایشی است و قطعاً باگ‌هایی دارد. هرگز طبق برنامه‌ریزی این نرم‌افزار غواصی نکنید مگر اینکه آن را با جداول یا نرم‌افزارهای مورد اعتماد خود بررسی کرده باشید، و هرگز بدون داشتن آموزش‌های رسمی برداشت فشار با گازهای مخلوط از آن استفاده نکنید.

مدل‌ها

* ZHL-16C — مجموعه Buhlmann با Gradient Factors یا درصد محافظه‌کاری، و ایست‌های عمیق اختیاری Pyle.
* VVAL-79 — مدل Thalmann EL-DCM نیروی دریایی آمریکا، با جذب نمایی و دفع خطی همراه با مجموعه پارامترهای ۹ بافتی منتشرشده برای هوا. فقط برای هوا، nitrox و اکسیژن: نیروی دریایی هیچ پارامتری برای هلیوم در این مدل منتشر نکرده است، بنابراین غواصی‌های حاوی هلیوم به جای محاسبه بر اساس اعداد ناموجود، رد می‌شوند. برای trimix از VPM-B یا ZHL-16C استفاده کنید.
* VPM-B — مدل نفوذپذیری متغیر Yount و Hoffman در پیاده‌سازی Erik Baker با سطح محافظه‌کاری ۰ تا ۴. بررسی‌شده با خروجی‌های منتشرشده خود Baker روی بنچمارک 80 msw trimix او: ۱۳ مورد از ۱۸ زمان ایست دقیقاً مطابقت دارند، با این تفاوت که اولین ایست یک گام ۳ متری عمیق‌تر بوده و ۴ دقیقه زمان کل ایست بیشتری دارد، به دلایلی که در دفترچه راهنما آمده است.

هر سه مدل از یک موتور برداشت فشار مشترک استفاده می‌کنند که به زبان C نوشته شده است و همان موتوری است که نسخه‌های macOS و iOS از آن بهره می‌برند. ورودی یکسان، برنامه‌ریزی کاملاً یکسانی را در تمام پلتفرم‌ها ارائه می‌دهد.

قابلیت‌ها

* غواصی‌های چندسطحی (Multi-level)، مدار باز یا مدار بسته، با setpointها و اسلاید Scamahorn.
* انتخاب خودکار گاز دکامپرشن بر اساس حداکثر PO2 و حداکثر END.
* غواصی‌های متوالی (Repetitive dives): بارگیری بافتی شما را حفظ می‌کند، آن را در زمان بسته بودن برنامه طبق زمان واقعی به‌روزرسانی می‌کند و پیش از برنامه‌ریزی مجدد از شما می‌خواهد زمان استراحت سطحی (surface interval) را مشخص کنید.
* پیگیری درصد CNS و OTU، میزان مصرف گاز برای هر مخلوط، و زمان مجاز برای پرواز (time to fly).
* هشدار چگالی گاز طبق فرمول Anthony و Mitchell.
* گرید ایست‌های قابل تنظیم، عمق آخرین ایست، بازه‌های سرعت صعود و فرود، و ایست‌های تمدیدشده هنگام تعویض گاز.
* ثبت، اشتراک‌گذاری و چاپ برنامه.

حریم خصوصی

این برنامه هیچ‌گونه دسترسی (permission) در Android درخواست نمی‌کند، از جمله دسترسی به اینترنت. برنامه نمی‌تواند هیچ اطلاعاتی را منتقل کند و هیچ‌گونه ابزار تحلیلی (analytics)، تبلیغاتی یا ردیابی در آن وجود ندارد. غواصی‌ها، تنظیمات و برنامه‌های ذخیره‌شده شما فقط در حافظه اختصاصی برنامه روی دستگاه باقی می‌مانند.

