UPDATE apps SET description_fa = 'برنامه Lens HRV یک اپلیکیشن Android است که تغییرپذیری ضربان قلب (HRV) را اندازه‌گیری می‌کند — یعنی میزان تغییر زمان بین ضربان‌های قلب شما از یک ضربه تا ضربه بعدی، که بر حسب میلی‌ثانیه سنجیده می‌شود. این برنامه از فتوفلتیسموگرافی (Photoplethysmography یا PPG) استفاده می‌کند؛ یک روش نوری ساده که تغییرات جزئی جریان خون در نوک انگشت شما را تنها با استفاده از دوربین و فلش گوشیتان تشخیص می‌دهد. کاملاً غیرتهاجمی است و به هیچ سنسور اضافی نیاز ندارد.

چرا HRV اهمیت دارد

تغییرپذیری ضربان قلب چیزی فراتر از یک اندازه‌گیری ساده برای قلب است. تغییرات کوچک بین ضربان‌های قلب شما از فرآیندهای متعددی ناشی می‌شوند که به‌طور هم‌زمان در بدن رخ می‌دهند. قلب شما به تنهایی کار نمی‌کند، بلکه دائماً با سایر بخش‌های بدن در تعامل است — سیستم عصبی، ریه‌ها، هورمون‌ها، دما، سیستم ایمنی، گوارش، چرخه‌های شبانه‌روزی، احساسات و موارد دیگر. HRV مانند یک میکروسکوپ عمل می‌کند که به ما اجازه می‌دهد این شبکه به‌هم‌پیوسته را مشاهده کنیم.

چه چیزی Lens HRV را متفاوت می‌کند

اکثر اپلیکیشن‌های HRV امروزی مانند جعبه‌های بسته عمل می‌کنند. آن‌ها معمولاً پولی هستند، به سنسورهای گران‌قیمت اضافی نیاز دارند و تنها اعداد نهایی حاصل از محاسبات خود را به شما نشان می‌دهند. شما به‌ندرت به سیگنال خام دسترسی پیدا می‌کنید. بسیاری از آن‌ها نیز وضعیت بدن را بیش از حد ساده کرده و آن را در قالب یک امتیاز یا رنگ واحد خلاصه می‌کنند.

برنامه Lens HRV کاملاً open source است. تمام الگوریتم‌های مورد استفاده در آن از تحقیقات علمی معتبر و داوری‌شده (peer-reviewed) که به‌صورت عمومی در دسترس هستند، گرفته شده‌اند. تمرکز برنامه به جای هوش مصنوعی سنگین، بر پردازش سیگنال دیجیتال کلاسیک است. این امر باعث می‌شود اپلیکیشن سبک و قابل درک باقی بماند و روی طیف وسیعی از دستگاه‌ها اجرا شود.

تمام داده‌ها مستقیماً روی گوشی شما پردازش می‌شوند — هیچ چیزی به cloud ارسال نمی‌شود. شما حریم خصوصی و کنترل کامل داده‌هایتان را حفظ می‌کنید.

این برنامه امتیاز «آمادگی» (readiness) ارائه نمی‌دهد. این نوع معيارها بیش از حد پیچیده و اغلب ساده‌انگارانه تلقی می‌شوند. در عوض، Lens HRV بر اندازه‌گیری‌های شفاف و ساده تمرکز دارد. هدف، ارائه ابزاری روان و بی‌دردسر است که برای همه در دسترس باشد.

نحوه کارکرد

انگشت اشاره خود را روی لنز دوربین قرار دهید تا پیش‌نمایش به رنگ قرمز تیره درآید. یک کالیبراسیون کوتاه، ضبط را آغاز می‌کند. انگشت خود را ثابت نگه دارید. پس از پایان، سیگنال کامل به‌صورت offline پردازش می‌شود. تنظیمات پیش‌فرض برای شرایط معمولی فضای بسته طراحی شده است.

آنچه دریافت می‌کنید

دامنه زمان (Time domain): ضربان قلب (Heart Rate)، RMSSD، SDNN و شاخص استرس (Stress Index).

دامنه فرکانس (Frequency domain): توان کل (Total Power)، LF، HF، نسبت LF/HF، اوج LF (LF Peak)، نرخ تنفس و امتیاز انسجام (Coherence Score).

هر جلسه همچنین آرتفکت‌ها و میزان پوشش را نشان می‌دهد. زیر ۵٪ عالی، زیر ۱۵٪ خوب و ۱۵٪ یا بیشتر نامعتبر است.

هر جلسه با یک خط پایه (baseline) ۷ روزه مقایسه می‌شود. از بخش تنظیمات می‌توانید داده‌های خود را به‌صورت CSV خروجی بگیرید (export کنید).

