• سلامت باتری - پایش افت باتری در طول زمان با نمودارهای بصری و شفاف
• آمار تخصصی - با لمس خودرو به آمارهای عمیق دسترسی پیدا کنید: رکوردها، بیشینه‌ها، نسبت شارژ AC به DC و جزئیات پنهان دیگر

آماده برای استفاده آفلاین

برنامه MateDroid داده‌های شما را به‌صورت محلی همگام‌سازی می‌کند تا بتوانید حتی بدون اتصال به اینترنت، سابقه رانندگی‌ها و شارژهای خود را مرور کنید؛ فوق‌العاده کاربردی برای بررسی تاریخچه سفرها در حین حرکت در جاده.

اول امتحان کنید، بدون نیاز به راه‌اندازی

هنوز سرور Teslamate ندارید؟ روی "Try the demo" در صفحه اول ضربه بزنید و کل برنامه را با یک سال داده‌های نمونه واقعی بررسی کنید — رانندگی‌ها، شارژها، یک جلسه شارژ زنده، آمارها و سلامت باتری. بدون نیاز به حساب کاربری، بدون مشخصات ورود و بدون نیاز به نصب چیزی. هر زمان که آماده بودید سرور خودتان را متصل کنید.

پیش‌نیازها

این برنامه به یک راه‌اندازی فعال از Teslamate + TeslamateApi نیاز دارد:
• Teslamate: github.com/adriankumpf/teslamate
• TeslamateApi: github.com/tobiasehlert/teslamateapi

اگر از قبل Teslamate را اجرا کرده‌اید، فقط با دیپلوی کردن یک API آماده استفاده از MateDroid خواهید بود.

