آشنایی با کنترل‌کننده‌های مختلف کامپوننت
Package Manager
سیستم‌عامل اندروید ابزاری به نام PackageManager ارائه می‌دهد که برای مدیریت برنامه‌های نصب‌شده یا دریافت اطلاعات مربوط به آن‌ها استفاده می‌شود. یکی از متدهای آن، setComponentEnabledSetting(ComponentName, int, int)، به برنامه اجازه می‌دهد وضعیت کامپوننت‌های خود را کنترل کند. در صورت تلاش برای استفاده از این متد جهت کنترل کامپوننت‌های سایر برنامه‌ها، نیاز به Signature Permission خواهد بود، در غیر این صورت فراخوانی ناموفق خواهد بود.

خوشبختانه اندروید ابزار دیگری به نام pm را ارائه می‌دهد که به کاربران امکان می‌دهد وضعیت کامپوننت‌ها را در حالت خط فرمان کنترل کنند. با این حال، اجرای ابزار pm نیازمند دسترسی Root است. از دستور زیر می‌توان برای غیرفعال کردن یک پکیج یا کامپوننت خاص استفاده کرد:

pm disable [PackageName/ComponentName]

چه از PackageManager در کد استفاده شود و چه از pm در حالت خط فرمان، این تنظیمات در مسیر /data/system/users/0/package_restrictions.xml ذخیره خواهند شد.

حالت Intent Firewall
قابلیت Intent Firewall در اندروید 4.4.2 (API 19) معرفی شد و همچنان در جدیدترین نسخه‌های اندروید نیز فعال است. این قابلیت درون Android Framework ادغام شده تا Intentهای ارسال‌شده توسط برنامه‌ها یا سیستم را فیلتر کند.

قابلیت‌های Intent Firewall
هر Intent ارسال‌شده توسط یک برنامه از فیلتر Intent Firewall عبور می‌کند و قوانین آن در فایل‌های XML ذخیره می‌شوند. در صورت بروز هرگونه تغییر در فایل پیکربندی، Intent Firewall بلافاصله قوانین را به‌روزرسانی می‌کند.

محدودیت‌های Intent Firewall
تنها برنامه‌های سیستمی اجازه خواندن و نوشتن در دایرکتوری محل ذخیره فایل پیکربندی را دارند و برنامه‌های Third-party دسترسی به آن ندارند.

تفاوت‌های میان Intent Firewall و Package Manager
قابلیت Intent Firewall همان‌طور که از نامش پیداست یک فایروال است و تأثیری بر وضعیت کامپوننت ندارد؛ برنامه فعال بودن کامپوننت را تشخیص می‌دهد، اما صرفاً قادر به اجرای آن نیست.

برای کامپوننت‌هایی که توسط PackageManager غیرفعال شده‌اند، در صورت اقدام برنامه به اجرای آن‌ها، یک Exception رخ می‌دهد. توسعه‌دهندگان می‌توانند این Exception را شناسایی کنند تا متوجه غیرفعال بودن کامپوننت شوند و دوباره آن را فعال کنند. دلیل اینکه گاهی کامپوننت‌ها به‌طور غیرمنتظره‌ای مجدداً فعال می‌شوند همین است. اگر از کنترل‌کننده Intent Firewall استفاده کنید، با چنین مشکلی مواجه نخواهید شد.

