حالت Tidy Speech برای حذف ایموجی‌ها و نمادها پیش از خواندن
ایجاد تاخیر در خواندن اعلان‌ها برای فرصت دادن به پایان صدای زنگ اعلان
زمان انتظار (cooldown) و حذف اعلان‌های تکراری برای جلوگیری از خواندن‌های پشت سر هم و آزاردهنده

منطق هوشمند و وابسته به شرایط

هماهنگ با حالت Do Not Disturb، تماس‌های تلفنی و حالت‌های صوتی سیستم
تشخیص دستگاه‌های Bluetooth (مثلاً خواندن فقط زمانی که هدفون یا سیستم صوتی خودرو متصل است)
تشخیص وضعیت صفحه نمایش (سکوت اختیاری در زمان روشن بودن صفحه)
زمان‌بندی ساعتی برای غیرفعال کردن خواندن در ساعات مشخص
قوانین شرطی برای عملکردهای پیشرفته (مانند منطق فقط در صورت اتصال به Bluetooth)

کنترل بدون دخالت دست (Hands-free)

تکان دادن گوشی برای توقف (Shake-to-stop) با حساسیت قابل تنظیم
رد کردن دست برای توقف (Wave-to-stop) با استفاده از سنسور مجاورت - ایده‌آل برای روی میز و استفاده بدون دست

اتوماسیون و کاربران پیشرفته

سازگار با برنامه‌های اتوماسیون مانند Tasker و MacroDroid
درون‌ریزی و برون‌بری (Import/Export) تنظیمات برای پشتیبان‌گیری آسان یا تعویض دستگاه
پشتیبانی از موتورهای TTS متفرقه در صورتی که موتور پیش‌فرض Android را نمی‌پسندید
ابزار عیب‌یابی داخلی برای کمک به رفع مشکلات تنظیمات پیچیده

سازگار با زبان‌ها و نیازهای دسترسی‌پذیری

پشتیبانی کامل از محلی‌سازی هم برای رابط کاربری و هم برای text-to-speech
ترجمه‌های جمع‌سپاری‌شده از طریق Weblate:
https://speakthat.app/translate

برنامه SpeakThat! هرگز داده‌های شما را به جایی ارسال نمی‌کند، مگر اینکه خودتان صراحتاً ارسال گزارش باگ را انتخاب کنید. آنچه در گوشی شما اتفاق می‌افتد، در گوشی شما باقی می‌ماند.

ایده‌آل برای افراد دارای نیازهای دسترسی‌پذیری، رانندگان و مسافران، محیط‌های کاری، ورزشکاران، والدین، افراد پرمشغله و هر کسی که می‌خواهد ارتباط سالم‌تری با اعلان‌های گوشی خود داشته باشد.

توسعه مداوم و فعال

برنامه SpeakThat! دائماً بر اساس بازخورد واقعی کاربران بهبود می‌یابد. این اپلیکیشن توسط کسی ساخته شده که خودش هر روز از آن استفاده می‌کند؛ یعنی قابلیت‌ها به این دلیل ساخته شده‌اند که واقعاً کاربردی هستند، نه برای این‌که در اسکرین‌شات‌های تبلیغاتی جذاب باشند یا صرفاً آماری را پر کنند.

ایمن بمانید، در جریان کارها باشید و اجازه دهید گوشی‌تان صحبت کند!', description_fa_source = 'machine' WHERE package_name = 'com.micoyc.speakthat' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'ویژگی‌ها:

برنامه My Location موقعیت مکانی دستگاه شما را از روش‌های زیر پیدا می‌کند:

- قابلیت GPS معمولاً دقیق‌ترین روش است؛ اما تثبیت موقعیت (position fix) ممکن است کمی طول بکشد یا به دلیل قطع سیگنال اصلاً انجام نشود. قابلیت Lock GPS یک سرویس مداوم را اجرا می‌کند تا اتصال به ماهواره‌ها حفظ شود.

همچنین می‌توانید فهرست ماهواره‌های قابل مشاهده را به همراه PRN (شناسه‌های منحصربه‌فرد) و SNR (کیفیت سیگنال) آن‌ها مشاهده کنید.

- بخش Network Location Provider برای تخمین موقعیت مکانی از شناسه‌های Wi-Fi یا شبکه همراه (Cellular) استفاده می‌کند. در دستگاه‌هایی که Google Play Services روی آن‌ها نصب است، NLP معمولاً در بک‌اند از Google Location Service استفاده می‌کند.

- سرویس UnifiedNLP یک API متن‌باز است که برای توسعه چندین بک‌اند مختلف NLP به کار رفته است (https://github.com/microg/UnifiedNlp/wiki/Backends).

علاوه بر این:
- مختصات موقعیت مکانی را می‌توان در کلیپ‌بورد کپی کرد یا در صورت نصب بودن برنامه نقشه، در آن باز کرد.
- پاک‌سازی داده‌های کمکی A-GPS نیز پشتیبانی می‌شود.

توجه داشته باشید که My Location مانند UnifiedNLP (یا microG GmsCore) یک ارائه‌دهنده موقعیت مکانی نیست؛ بلکه صرفاً اطلاعات مکانی دریافت‌شده از ارائه‌دهندگان موقعیت مکانی در AOSP (شامل GPS و Network) یا مستقیماً از بک‌اندهای UnifiedNLP (هرکدام که در دستگاه موجود باشد) را نمایش می‌دهد.', description_fa_source = 'machine' WHERE package_name = 'com.mirfatif.mylocation' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
