UPDATE apps SET description_fa = 'توضیحات: برنامه‌ی Health Disconnect به شما امکان می‌دهد داده‌های سلامت شخصی خود را دقیقاً روی دستگاهتان بررسی کنید — بدون نیاز به حساب کاربری، بدون اینترنت و بدون جمع‌آوری داده‌ها.

به Android Health Connect متصل شوید و فوراً بیش از ۳۵ متریك سلامت را به صورت نمودارهای تعاملی مشاهده کنید. نماهای سفارشی بسازید که چندین متریك را ترکیب می‌کنند، نوع نمودار، روش‌های تجمیع و بازه‌های زمانی را تنظیم کنید، و سپس آن‌ها را به عنوان ویجت به صفحه اصلی خود سنجاق کنید.

داده‌های شما روی دستگاهتان باقی می‌ماند
برنامه‌ی Health Disconnect هرگز به اینترنت متصل نمی‌شود. این برنامه داده‌های Health Connect شما را می‌خواند، آن‌ها را به صورت محلی پردازش و رندر می‌کند و هرگز هیچ چیزی را ارسال نمی‌کند. هیچ حساب کاربری، هیچ ابزار تحلیلی (analytics) و هیچ تبلیغاتی وجود ندارد.

ویژگی‌های کلیدی

• مرور بیش از ۳۵ متریك Health Connect — گام‌ها، ضربان قلب، وزن، خواب، فشار خون، تغذیه و موارد دیگر
• نمودارهای تعاملی — نمودارهای خطی و میله‌ای با قابلیت تنظیم تجمیع داده‌ها (مجموع، میانگین، حداقل، حداکثر)
• نماهای سفارشی — ترکیب چندین متریك در یک نمودار و ذخیره برای دسترسی سریع
• بازه‌های زمانی انعطاف‌پذیر — مشاهده داده‌ها به تفکیک روز، هفته، ماه، سال یا کل تاریخچه
• ویجت‌های صفحه اصلی — سنجاق کردن هر نمای سفارشی به عنوان ویجت قابل تغییر اندازه با فواصل به‌روزرسانی قابل تنظیم
• خروجی گرفتن از داده‌ها — ذخیره مقادیر تجمیع‌شده یا ورودی‌های خام به صورت فایل CSV
• اشتراک‌گذاری نمودارها — خروجی گرفتن از تصاویر نمودار در تم روشن یا تاریک
• تنظیمات پیشرفته — محورهای Y لگاریتمی و نرمال‌سازی‌شده، هموارسازی داده‌ها (data smoothing)، اندازه دسته‌ها (bucket sizes)، واحدهای سفارشی، برچسب‌های حداقل/حداکثر
• پشتیبانی از تم — پیروی از تم سیستم یا انتخاب دستی تم روشن/تاریک

داده‌های پشتیبانی‌شده در HEALTH CONNECT

تناسب اندام و فعالیت: گام‌ها، مسافت، سرعت، ورزش، طبقات طی‌شده، ارتفاع گرفته‌شده، توان، حرکت با ویلچر (Wheelchair Pushes)

قلبی عروقی: ضربان قلب، ضربان قلب در حال استراحت، تغییرپذیری ضربان قلب (HRV)، فشار خون، اشباع اکسیژن، VO2 Max

بدن: وزن، قد، چربی بدن، جرم عضلانی/بدون چربی، جرم استخوان، میزان آب بدن، نرخ سوخت‌وساز پایه (BMR)

تغذیه: میزان آبرسانی، تغذیه، کالری فعال سوزانده‌شده، کل کالری سوزانده‌شده

سایر موارد: دمای بدن، دمای پایه بدن، نرخ تنفس، خواب، قاعدگی، مخاط دهانه رحم، تست تخمک‌گذاری، خونریزی بین قاعدگی، فعالیت جنسی

اولویت با حریم خصوصی
برنامه‌ی Health Disconnect فاقد هرگونه مجوز دسترسی به شبکه است. داده‌های سلامت شما از Health Connect خوانده شده، روی صفحه نمایش داده می‌شوند و هرگز از دستگاه شما خارج نمی‌شوند، مگر اینکه خودتان صریحاً خروجی گرفتن یا اشتراک‌گذاری را انتخاب کنید.

نکته‌ای که بد نیست بدانید: این برنامه در پشتیبان‌گیری استاندارد Android شرکت می‌کند؛ بنابراین اگر پشتیبان‌گیری دستگاه شما روشن باشد، نماهای ذخیره‌شده‌ی شما — شامل نام آن‌ها، تنظیمات نمودار و اینکه چه نوع داده‌هایی را ترسیم می‌کنند — در آن قرار می‌گیرند. هیچ اندازه‌گیری سلامتی توسط برنامه ذخیره یا پشتیبان‌گیری نمی‌شود؛ آن‌ها در Health Connect باقی می‌مانند. می‌توانید این قابلیت را در تنظیمات پشتیبان‌گیری دستگاه خود غیرفعال کنید.', description_fa_source = 'machine' WHERE package_name = 'com.monkopedia.healthdisconnect' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
