UPDATE apps SET description_fa = 'توضیحات: Flux یک ویدیو پلیر مدرن و شیک است که برای تبدیل فایل‌های محلی شما به یک آرشیو جذاب و فراگیر طراحی شده است.

چرا Flux را انتخاب کنیم؟

کتابخانه منظم: اطلاعات فیلم‌ها، سریال‌ها و انیمه‌های شما از طریق سرویس TMDB دریافت می‌شود تا در قالب یک کتابخانه ساده و کارآمد سازمان‌دهی شوند.
رابط کاربری مدرن: از ترکیب Material 3 Expressive و Material You برای برنامه‌ای با طراحی مدرن لذت ببرید.
پخش‌کننده داخلی: علاوه بر داشتن یک کتابخانه زیبا، می‌توانید فایل‌های خود را مستقیماً از داخل برنامه پخش کنید.
کاملاً رایگان: بدون اشتراک، بدون تبلیغات و بدون ردیاب. این برنامه کاملاً رایگان است و رایگان باقی خواهد ماند.

چه طرفدار انیمه باشید، چه عاشق سینما، یا صرفاً به برنامه‌ای برای پخش فایل‌هایتان نیاز داشته باشید، Flux شما را به تماشای مداوم فیلم‌ها و سریال‌هایتان ترغیب می‌کند.

نکته: Flux یک پروژه Open Source است که توسط یکی از علاقه‌مندان به Android توسعه یافته؛ کسی که متعهد به ارائه تجربه‌ای دلنشین، ساده و با کارایی بالاست.', description_fa_source = 'machine' WHERE package_name = 'com.mskd.flux' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
