این برنامه در پس‌زمینه اجرا می‌شود و می‌توانید آن را از پنل Quick Settings روشن و خاموش کنید.

تشخیص

- Head tracking: چرخش صورت به سمت صفحه به عنوان نگاه کردن محسوب می‌شود. کمترین مصرف باتری را دارد.
- Eye tracking: عنبیه چشم‌ها را دنبال کرده و آن را با زاویه سر ترکیب می‌کند، بنابراین تنها زمانی هشدار می‌دهد که چشم‌ها دقیقاً به سمت صفحه اشاره داشته باشند.
- چهره خود شما تشخیص داده شده و نادیده گرفته می‌شود، و چهره‌هایی که خیلی دور هستند و نمی‌توانند صفحه را بخوانند به حساب نمی‌آیند.
- یک نمای Debug به‌صورت زنده آنچه را که آشکارساز می‌بیند و دلیل حساب شدن یا نشدن هر چهره را نشان می‌دهد.

حفظ حریم خصوصی از پایه

فرآیند تشخیص به‌صورت آفلاین و روی خود گوشی با مدل‌های متن‌باز همراه برنامه (YuNet و MediaPipe Face Landmarker) انجام می‌شود. بدون هیچ‌گونه ابزار تحلیلی (Analytics)، تبلیغات یا حساب کاربری.
هیچ اطلاعاتی از گوشی خارج نمی‌شود مگر اینکه آن را با سرور RWR شخصی خود (Docker، متن‌باز، موجود در همان مخزن) جفت کنید. در این صورت فریم‌ها تنها از طریق TLS به سرور شما ارسال می‌شوند: فرآیند تشخیص در آنجا با نرخ فریم کامل و بدون خالی کردن باتری گوشی انجام می‌شود و تصاویر را می‌توان روی Immich آپلود کرد.
دوربین در زمان خاموش بودن صفحه همیشه خاموش است. Android در زمانی که RWR در حال پایش است، نشانگر دوربین را نشان می‌دهد.

نیازمند Android 10 یا جدیدتر و دوربین جلو است. نمایش پاپ‌آپ به مجوز «Display over other apps» نیاز دارد.', description_fa_source = 'machine' WHERE package_name = 'io.github.revocx35.rwr' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
