UPDATE apps SET description_fa = 'Rufid گوشی اندروید شما را به یک ابزار کاربردی برای ساخت درایو بوت USB تبدیل می‌کند.

این برنامه فایل‌های ISO/IMG محلی را روی حافظه‌های متصل‌شده USB می‌نویسد، ایمیج‌ها را مستقیماً از لینک URL استریم می‌کند، یک درایو کوچک FreeDOS می‌سازد، صحت اطلاعات نوشته‌شده را بررسی می‌کند، بوتیبل بودن و رکوردهای بوت را بازرسی می‌کند، بنچمارک خواندن اجرا می‌کند، از درایو USB روی حافظه اندروید پشتیبان می‌گیرد، فایل‌های ZIP را استخراج می‌کند و حافظه بوتیبل استفاده‌شده را دوباره به یک درایو معمولی FAT32 یا exFAT بازمی‌گرداند.

فایل‌های ISO نصب Windows می‌توانند به صورت چیدمان FAT32 UEFI نوشته شوند (که در صورت عبور فایل install.wim از محدودیت حجم فایل FAT32، آن را تقسیم می‌کند)، یا به صورت یک پارتیشن داده NTFS با چیدمان کمکی MBR یا GPT UEFI:NTFS نوشته شوند. این روش‌ها در محیط QEMU/OVMF تا صفحه انتخاب زبان Windows Setup بوت و تست شده‌اند. با این حال، کنترلرهای فیزیکی USB و فیرم‌ور رایانه، نیازمند تست سازگاری جداگانه هستند.

روند اصلی برنامه کاملاً مبتنی بر گوشی است: حافظه USB را انتخاب کنید، آن را بررسی کنید، منبع ISO/IMG، لینک URL یا FreeDOS را برگزینید، مراحل کار را مرور کرده، عملیات نوشتن را انجام دهید و صحت آن را تایید کنید. حالت URL مستقیم شامل دسترسی سریع به صفحات رسمی دانلود Windows، Ubuntu، Fedora، Debian، Linux Mint، Arch Linux و openSUSE است؛ این برنامه ایمیج این سیستم‌عامل‌ها را درون خود ندارد.

عملیات حساس و پاک‌کننده USB توسط یک صفحه نمایش جزئیات و تایید صریح محافظت می‌شوند. Rufid قبل از انجام عملیات نوشتن یا بازیابی، حافظه USB انتخاب‌شده، حجم آن و شناسه سخت‌افزاری موجود را نشان می‌دهد. این برنامه برای حافظه‌های جانبی USB طراحی شده است، نه حافظه داخلی اندروید.

برنامه Rufid فاقد هرگونه SDK تبلیغاتی، SDK آنالیتیکس، SDK پرداخت درون‌برنامه‌ای، وابستگی به Firebase، سیستم حساب ابری یا SDK گزارش‌دهی خطای از راه دور است. گزارش‌های خطا به صورت محلی روی دستگاه باقی می‌مانند.

ساختار بیلد F-Droid مجموعه پی‌لودهای بوت را از ورودی‌های قابل بازرسی بسته‌بندی می‌کند. FreeDOS از کرنیل سورس‌کد ساخته‌شده FreeDOS، FreeCOM، SYS و فایل‌های بوت‌سکتور سرهم‌بندی شده است. ابزارهای UEFI:NTFS، wimlib، NTFS-3G و 7-Zip-JBinding از سورس‌کدهای مبدا مشخص شده آماده شده‌اند و بیلد اندروید 7-Zip-JBinding شامل سورس‌کدهای نیتیو RAR/unRAR نمی‌شود. هیچ پی‌لودی از APKهای مبهم شخص ثالث استخراج نشده است.

بازیابی USB شامل پاک‌سازی سریع متادیتا و فرمت به صورت FAT32 یا exFAT است. این فرآیند برای بازگرداندن USB بوتیبل به حالت استفاده معمولی مفید است، اما به منزله پاک‌سازی امن (secure erase) یا پاک‌سازی کامل کل دیسک نیست.', description_fa_source = 'machine' WHERE package_name = 'io.github.rufid' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'یک پوشه انتخاب کنید. عکس‌هایتان را بگیرید. هر عکس را دقیقاً سر جای خودش نگه دارید.

برنامه Folder Camera یک دوربین نیتیو Android برای دسته‌بندی عکس‌ها هم‌زمان با ثبت آن‌هاست. با ابزار انتخاب پوشه Android یک base directory انتخاب کنید، سپس پیش از عکاسی یک relative path وارد یا انتخاب نمایید. پوشه‌های تودرتو، فاصله‌های معمولی و نام‌های Unicode پشتیبانی می‌شوند.

• ثبت مستقیم عکس‌های JPEG در پوشه‌ای که تأیید کرده‌اید
• یافتن مسیرهای مقصد با استفاده از درخت پوشه قابل جستجو
• تغییر پوشه‌ها بین نشست‌های عکاسی بدون جایگزین شدن عکس‌های موجود
• استفاده از زوم لمسی (pinch) یا اسلایدر و حالت‌های نوری Off، Auto، Flash یا Always-on (در صورت پشتیبانی دوربین)
• پیش‌نمایش، اشتراک‌گذاری و خروجی گرفتن از عکس‌ها از طریق Android
• در دسترس ماندن عکس‌های ذخیره‌شده برای سایر برنامه‌ها و حتی پس از لغو نصب
• عکاسی بدون نیاز به PC، حساب کاربری یا اتصال اینترنت

انتقال اختیاری تحت شبکه (LAN)
با گیرنده رایگان و open-source دسکتاپ جفت (Pair) شوید تا نسخه‌ای از عکس‌ها مستقیماً از طریق HTTPS با گواهی معتبر به PC ارسال شود. همگام‌سازی (Sync) به‌طور پیش‌فرض خاموش است. انتقال‌های در انتظار در صورت قطعی موقت ارتباط حفظ شده و مسیر مقصد اصلی خود را نگه می‌دارند. در اولین اجرای گیرنده، یک آدرس LAN خصوصی به‌طور خودکار انتخاب شده و یک QR کد برای جفت‌سازی نمایش داده می‌شود.

حریم خصوصی و کنترل
بدون تبلیغات، analytics یا سرور عکس اختصاصی توسعه‌دهنده. بدون دسترسی کلی به تمام فایل‌ها (all-files access). شما پوشه‌های Android و PC را به‌طور مستقل انتخاب می‌کنید. این برنامه یک نرم‌افزار open-source با مجوز GPL-3.0-or-later است؛ کد منبع (source code) و پشتیبانی از طریق وب‌سایت پروژه در دسترس است.

گیرنده دسکتاپ در حال حاضر از Linux پشتیبانی می‌کند و به Deno و OpenSSL نیاز دارد. آپلود اختیاری به PC برای عکاسی محلی ضروری نیست. زمان‌بندی آپلود در پس‌زمینه توسط Android کنترل می‌شود. پیش از لغو نصب، فایل‌های بخش staging اختصاصی را بازیابی/خروجی بگیرید؛ متادیتای اختصاصی برنامه و اطلاعات جفت‌سازی پس از لغو نصب باقی نمی‌مانند.', description_fa_source = 'machine' WHERE package_name = 'io.github.sigmasd.foldercamera' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
