UPDATE apps SET description_fa = 'توضیحات: TT9 یک کیبورد T9 دوازده کلیده به سبک Nokia است. این برنامه امکان تایپ پیش‌بینانه متن به بیش از ۴۰ زبان، کلیدهای میانبر قابل تنظیم، کلیپ‌بورد، undo/redo و شخصی‌سازی‌های گسترده را فراهم می‌کند. این کیبورد روی صفحه‌نمایش‌های لمسی، کیبوردهای فیزیکی و کنترل‌های ریموت TV کار می‌کند. و از همه بهتر، از شما جاسوسی نمی‌کند!

زبان‌های پشتیبانی‌شده: عربی، بلغاری، کاتالان، چینی ساده‌شده (Pinyin)، کرواتی، چکی، دانمارکی، هلندی، انگلیسی، استونیایی، فارسی، فنلاندی، فرانسوی، آلمانی، یونانی، گوجراتی (صوتی)، عبری، هندی (صوتی)، هینگلیش، مجاری، اندونزیایی، ایرلندی، ایتالیایی، ژاپنی (Romaji)، سواحیلی، کره‌ای، لتونیایی، لیتوانیایی، نروژی، لهستانی، پرتغالی (اروپایی و برزیلی)، رومانیایی، روسی، صربی (سیریلیک)، اسلواکی، اسلوونیایی، اسپانیایی، سوئدی، آمازیغی مراکشی (لاتین و Tifinagh)، تایلندی، توکی پونا، ترکی، اوکراینی، ویتنامی، یدیش.

فلسفه:
- بدون هیچ‌گونه جاسوسی، ردگیری، telemetry، گزارش‌دهی یا جمع‌آوری داده از هر نوعی.
- بدون تبلیغات یا قابلیت‌های اضافی و غیرضروری. فقط وظیفه خود یعنی تایپ کردن را انجام می‌دهد.
