- متن‌باز (Open-source)، که به شما اجازه می‌دهد خودتان تمام موارد بالا را راستی‌آزمایی کنید.
- ساخته‌شده با کمک تمام جامعه کاربری.
- مواردی که (احتمالاً) هرگز نخواهد داشت: چیدمان QWERTY، تایپ سوییپی (swipe)، فایل‌های GIF و استیکر.
- هدف آن ارائه یک کپی از TouchPal، Sony Ericsson، KaiOS، Samsung و غیره نیست. اگرچه حس‌وحال کیبوردهای کلاسیک را بازسازی می‌کند، اما TT9 تجربه خاص خود را ارائه می‌دهد و هیچ دستگاه یا برنامه‌ای را دقیقاً بازآفرینی نخواهد کرد.

نکته: نسخه Google Play تقریباً با نسخه Lite یکسان است، با این تفاوت که شامل ویژگی‌های اضافی «پریمیوم» است که closed-source هستند. با این حال، هیچ‌یک از اجزای اضافی، اصول ذکرشده در بالا را به خطر نمی‌اندازند.', description_fa_source = 'machine' WHERE package_name = 'io.github.sspanak.tt9' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'توضیحات: به راحتی و با کشیدن و رها کردن (drag-and-drop) ساده، رابط‌های کنترلی سفارشی بسازید و دستگاه اندروید خود را به یک کنترل از راه دور برای پروتکل‌های Bluetooth Low Energy (BLE)، WebSocket، MQTT، Bluetooth، TCP و UDP تبدیل کنید.

ویژگی‌های کلیدی:

1. ساخت صفحه کنترل با Drag-and-Drop:
   صفحه‌های کنترل خود را با کشیدن و رها کردن اجزایی مانند دکمه‌ها، اسلایدرها و سوئیچ‌ها طراحی کنید.

2. پشتیبانی از چند پروتکل و اتصال انعطاف‌پذیر:
    - برای WebSocket، MQTT، TCP، UDP و Bluetooth، برنامه به عنوان client عمل می‌کند و با اتصال به سرورها، امکان تعامل آنی (real-time) را از طریق اجزای صفحه کنترل فراهم می‌سازد.
    - برای Bluetooth Low Energy (BLE)، برنامه به عنوان یک دستگاه جانبی (GATT server) عمل می‌کند و تعاملاتی مانند فشردن دکمه، تغییر اسلایدر و تغییر وضعیت سوئیچ را از طریق اعلان‌های BLE اطلاع‌رسانی می‌کند.

3. تغییر نوع اتصال در هر زمان:
   می‌توانید نوع اتصال یک صفحه کنترل را در هر زمانی تغییر دهید، بدون اینکه نیازی به ساخت یک نسخه کپی برای اتصالی دیگر داشته باشید.

4. به‌روزرسانی UI از طریق اسکریپت خود:
   می‌توانید وضعیت SWITCH، SLIDER، LED و GAUGE را از طریق اسکریپت خود تغییر دهید.

