UPDATE apps SET description_fa = 'برنامه WallosMobile یک کلاینت غیررسمی Kotlin Multiplatform برای Wallos است؛ ابزار متن‌باز و self-hosted برای مدیریت و ردیابی اشتراک‌ها. این برنامه هیچ وابستگی به پروژه Wallos ندارد و برای اتصال به آن، به سرور Wallos اختصاصی خود نیاز دارید.

