برنامه openScale sync یک برنامه مکمل است: این برنامه نیاز دارد که برنامه مجزای openScale (یک برنامه ترازو با قابلیت Bluetooth برای سنجش ترکیب بدن) نصب شده باشد. این برنامه هیچ اندازه‌گیری را به صورت مستقل ذخیره نمی‌کند، بلکه آن‌ها را از openScale می‌خواند و به سرویس‌هایی که فعال کرده‌اید ارسال می‌کند. همچنین می‌تواند اندازه‌گیری‌ها را در جهت عکس نیز به openScale بازگرداند.

ویژگی‌ها:
* ادغام یکپارچه با سرویس‌های خارجی: همگام‌سازی آسان داده‌ها با Health Connect، Wger، Endurain، InfluxDB، Webhookهای عمومی و MQTT (نسخه‌های 3.1 و 5.0، شامل شناسایی خودکار Home Assistant).
* همگام‌سازی آنی: همگام‌سازی خودکار داده‌ها بلافاصله پس از افزودن، ویرایش، حذف یا پاک‌سازی اندازه‌گیری‌ها در openScale.
* همگام‌سازی دوطرفه: اندازه‌گیری‌هایی که برنامه‌های دیگر در Health Connect، Wger یا MQTT ثبت کرده‌اند را می‌توان به openScale وارد کرد تا اطلاعاتی که ترازو ثبت نکرده است تکمیل شوند. هر سرویس تنظیمات جهت اختصاصی خود را دارد: فقط خروجی، فقط ورودی، یا هر دو.
* همگام‌سازی اختیاری در پس‌زمینه: به برنامه اجازه دهید هر چند ساعت یک‌بار همه‌چیز را تطبیق دهد، تا اگر همگام‌سازی آنی انجام نشد، به عنوان یک پشتیبان عمل کند.
* همگام‌سازی کامل به درخواست کاربر: شروع دستی همگام‌سازی کامل داده‌ها در هر زمان که نیاز باشد.
* تلاش مجدد خودکار: همگام‌سازی ناموفق، به‌طور خودکار با داده‌های فعلی مجدداً تلاش می‌شود و هر اندازه‌گیری که هنوز در صف انتظار است به شما نشان داده می‌شود.
* پشتیبانی از چند کاربر: سرویس‌های MQTT، InfluxDB و Webhook اطلاعات هر کاربر openScale را به صورت مجزا نگه‌داری می‌کنند؛ Health Connect، Wger و Endurain کاربر انتخابی شما را همگام‌سازی می‌کنند.
* فعال‌سازی قابل تنظیم سرویس‌ها: به‌راحتی سرویس‌های خارجی مختلف را فعال یا غیرفعال کنید تا تنظیمات همگام‌سازی طبق نیاز شما انجام شود.
* سرویس پیش‌زمینه هوشمند: استفاده از یک سرویس پیش‌زمینه که تنها در صورت نیاز فعال می‌شود تا مصرف باتری به حداقل برسد.
* رابط کاربری آسان: بهره‌مندی از یک رابط کاربری گرافیکی کاربرپسند برای کنترل و جابه‌جایی راحت در برنامه.

