UPDATE apps SET description_fa = 'توضیحات: یک ضبط‌کننده مکالمه برای اندروید بدون روت. یک فایل APK. بدون روت، بدون Shizuku، بدون برنامه جانبی، بدون کامپیوتر: گوشی همه کارها را خودش انجام می‌دهد.

نحوه کارکرد. منبع صوتی مکالمه تلفنی در اندروید شامل صدای هر دو طرف است، اما دسترسی به آن نیازمند مجوزهایی است که هیچ برنامه معمولی ندارد. کاربر Shell که جلسات ADB تحت آن اجرا می‌شود، این مجوزها را دارد. برنامه JemRec شامل یک کلاینت ADB داخلی است و از طریق 127.0.0.1 با Wireless debugging خود گوشی جفت (Pair) می‌شود؛ دقیقاً مانند همان جفت‌سازی ۶ رقمی که یک لپ‌تاپ انجام می‌دهد، با این تفاوت که هر دو طرف روی خود گوشی قرار دارند. هیچ اطلاعاتی از گوشی خارج نمی‌شود.

جلسه ADB فقط چند ثانیه طول می‌کشد، اگرچه خود دیباگینگ روشن می‌ماند (به ادامه متن مراجعه کنید). در این مدت، برنامه یک Daemon کوچک با دسترسی‌های shell را اجرا کرده و سپس جلسه را می‌بندد. این Daemon وضعیت تماس را زیر نظر گرفته و هر مکالمه را روی یک فایل ذخیره می‌کند؛ برنامه اصلاً در مسیر صوت قرار ندارد و هیچ مجوز میکروفونی هم ندارد. تمام ارتباطات بین این دو بخش، دوطرفه و از طریق توکنی که هرگز از سوکت عبور نمی‌کند احراز هویت می‌شوند.

فایل‌های ضبط‌شده با فرمت Opus در قالب Ogg و در پوشه استاندارد Recordings/JemRec گوشی ذخیره می‌شوند، جایی که هر برنامه مدیریت فایل یا پخش‌کننده موسیقی می‌تواند آن‌ها را باز کند. حالت خودکار تمام تماس‌ها را ضبط می‌کند؛ حالت «پرسش قبل از ضبط» تا زمانی که روی دکمه Record در اعلان شروع تماس ضربه نزنید، چیزی ضبط نمی‌کند.

راه‌اندازی فقط یک‌بار و با دو اقدام دستی انجام می‌شود: فعال کردن Developer options، سپس USB debugging و Wireless debugging، و وارد کردن کد جفت‌سازی در اعلان JemRec. جفت‌سازی بعد از ری‌استارت باقی می‌ماند، اما ضبط‌کننده این‌طور نیست: بعد از ری‌استارت، اگر گوشی اجازه شروع خودکار به JemRec بدهد، دفعه بعدی که Wi-Fi روشن شود ضبط‌کننده به‌طور خودکار بازسازی می‌شود. در بخش تنظیمات کارت ویژه‌ای وجود دارد که صفحه مربوط به این کار را باز می‌کند. شبکه Wi-Fi فقط برای بازسازی ضبط‌کننده لازم است و برای خودِ ضبط مکالمه هرگز نیازی به آن نیست.

چه مواردی روشن می‌مانند. گزینه USB debugging و Wireless debugging تا زمانی که JemRec نصب است روشن می‌مانند و اگر خاموش شوند، JemRec دوباره آن‌ها را روشن می‌کند؛ زیرا ضبط‌کننده بدون آن‌ها کار نمی‌کند. در زمان روشن بودن این گزینه‌ها، کامپیوتری که قبلاً با گوشی جفت شده باشد می‌تواند از طریق همان شبکه Wi-Fi به آن متصل شود. اندروید هنگام روشن بودن دیباگ، یک اعلان نشان می‌دهد؛ در مراحل راه‌اندازی از شما پرسیده می‌شود که آیا JemRec آن را پنهان کند یا خیر، و بعداً در Settings می‌توانید این تصمیم را تغییر دهید. برای خاموش کردن همیشگی دیباگ، ابتدا JemRec را لغو نصب کنید.

پیش‌نیازها. اندروید ۱۲ یا جدیدتر، و گوشی‌ای که سخت‌افزار صوتی آن منبع مکالمه صوتی را تحویل دهد. این موضوع در سازندگان مختلف متفاوت است و راه میانبری ندارد: برخی گوشی‌ها صدای هر دو طرف، برخی یک طرف و برخی سکوت تحویل می‌دهند. صدای هر دو طرف روی Honor Magic 8 Pro، Samsung Galaxy S20 و یک OnePlus با LineageOS ضبط شده است. بخش Settings ← Diagnostics ← Self-test ظرف حدود یک ثانیه وضعیت را برای گوشی شما مشخص می‌کند.

مسئولیت ضبط مکالمات بر عهده شماست. قوانین مربوط به رضایت طرفین در کشورها و گاهی در ایالت‌های مختلف متفاوت است. این برنامه همان چیزی را ضبط می‌کند که به آن دستور می‌دهید و از طرف شما به هیچ‌کس هشداری نمی‌دهد.

آنچه برنامه درخواست نمی‌کند: بدون RECORD_AUDIO، بدون دسترسی کلی به حافظه ذخیره‌سازی، بدون دسترسی به وضعیت گوشی (phone state). مجوز INTERNET توسط اندروید برای هرگونه سوکت TCP الزامی است، از جمله اتصال به 127.0.0.1 که تنها آدرسی است که این برنامه به آن متصل می‌شود. دسترسی READ_MEDIA_AUDIO تنها برای فهرست کردن ضبط‌های انجام‌شده قبل از نصب مجدد درخواست می‌شود. مجوزهای READ_CALL_LOG و READ_CONTACTS اختیاری هستند و فقط برای برچسب‌گذاری فایل‌ها با نام یا شماره مخاطب استفاده می‌شوند. دسترسی به اعلانات (Notification access) تنها در صورتی اعطا می‌شود که از JemRec بخواهید اعلان دیباگ اندروید را مخفی کند و برای هیچ منظور دیگری استفاده نمی‌شود.', description_fa_source = 'machine' WHERE package_name = 'com.jemcik.jemrec' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'تایمر Pomodoro که فقط در یک خانه جا می‌شود.

همه برنامه‌های Pomodoro حداقل یک ویجت ۲×۲ دارند که صفحه اصلی شما را اشغال می‌کند. «¡Aquí hay tomate!» یک ویجت تک‌خانه‌ای دارد: یک بار لمس برای شروع یا توقف، دو بار لمس برای بازنشانی. بدون نیاز به باز کردن برنامه، بدون معطلی.

۲۵ دقیقه کار کنید، ۵ دقیقه استراحت کنید و بعد از هر چهار Pomodoro یک استراحت طولانی داشته باشید. یا آن را هر طور که دوست دارید تنظیم کنید — تمام زمان‌بندی‌ها دست شماست.

کاملاً قابل اعتماد. دقیقاً سر ثانیه موعود هشدار می‌دهد؛ حتی زمانی که صفحه خاموش است، برنامه را بسته‌اید یا گوشی را ری‌استارت کرده‌اید. تایمری که تاخیر داشته باشد، اصلاً تایمر نیست.

و البته خوش‌ساخت و زیبا. یک پس‌زمینه مشکی و یک گوجه‌فرنگی قرمز که با گذشت زمان خالی می‌شود. بدون دکمه‌های غول‌پیکر و رابط کاربری بچگانه.

ویژگی‌های اصلی:

• ویجت 1×1 صفحه اصلی: شروع، توقف و reset بدون نیاز به باز کردن برنامه
• چرخه‌های کامل تمرکز، استراحت کوتاه و استراحت بلند
• قابلیت تنظیم تمام زمان‌بندی‌ها و تعداد Pomodoroها در هر چرخه
• آمارها: Pomodoroهای تکمیل‌شده، زمان تمرکز، زنجیره روزانه (streak)، نقشه ماهانه و روند پیشرفت
• هشدار پایان هر بازه زمانی با صدا و تعداد تکرار اختصاصی برای هر بخش
• امکان تنظیم مدت‌زمان ویبره
• شروع خودکار اختیاری برای بازه زمانی بعدی
• Notification همراه با شمارش معکوس و دکمه‌های توقف، رد کردن و reset
• سازگار با حالت Silent و Do Not Disturb
• پشتیبانی از زبان‌های اسپانیایی و انگلیسی

