نام این برنامه یک بازی با کلمات به زبان اسپانیایی است: Pomodoro در زبان ایتالیایی به معنای گوجه‌فرنگی است که نام این تکنیک هم از آن گرفته شده. و بله، این نام گریزی هم به یک آگهی تبلیغاتی قدیمی رب گوجه‌فرنگی می‌زند.', description_fa_source = 'machine' WHERE package_name = 'com.jjrapps.aquihaytomate' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'Daybook یک اپلیکیشن پازل‌های منطقی روزانه برای کسانی است که به فکر کردن علاقه دارند.

هر روز مجموعه‌ای تازه از پازل‌های منطقی کلاسیک ارائه می‌شود: Sudoku، پازل‌های ناحیه‌ای و جاگذاری، جدول‌های عدد، علامت و نماد، شبکه‌های لوله‌کشی، پر کردن همسایگی (flood-fill)، مسیرهای تک‌خطی، کدشکنی و پازل‌های مات در N حرکت شطرنج. هر پازل در سه سطح سختی Standard، Hard و Expert ارائه می‌شود و طوری طراحی شده که دقیقاً یک پاسخ مشخص دارد که فقط با استدلال منطقی به آن می‌رسید. هیچ‌چیز نیازی به حدس زدن ندارد.

بدون تبلیغات. بدون اشتراک. بدون حساب کاربری.
هیچ تبلیغ، Paywall، ورود به حساب یا خرید درون‌برنامه‌ای وجود ندارد. این برنامه حتی دسترسی به شبکه هم نمی‌خواهد، بنابراین در هواپیما، قطار و داخل تونل به راحتی کار می‌کند.

آرشیو کامل، از روز اول
پازل‌ها بر اساس تاریخ روی دستگاه شما ساخته می‌شوند، بنابراین تمام روزهای گذشته از قبل آماده هستند. یک هفته را از دست داده‌اید؟ آن را بازی کنید. تنوع بیشتری می‌خواهید؟ در هر سطح سختی، به صفحه‌های Random بروید.

حین بازی یاد بگیرید
گیر کرده‌اید؟ درخواست راهنمایی کنید تا Daybook قدم بعدی را به زبانی ساده توضیح دهد و به جای پر کردن مستقیم یک خانه، به خانه‌های مورد نظر اشاره کند. هر پازل یک راهنمای کوتاه برای تازه‌کارها دارد و بخش «روش بازی» همیشه تنها با یک لمس در دسترس است.

Streak خود را حفظ کنید
روند روزانه (Streak)، زمان‌ها و آمار خود را پیگیری کنید؛ همگی به صورت کاملاً خصوصی روی گوشی شما ذخیره می‌شوند.

طراحی‌شده با اولویت حریم خصوصی
Daybook هیچ اطلاعاتی جمع‌آوری نمی‌کند. بدون ابزارهای Analytics، بدون ردیاب و بدون SDKهای شخص ثالث. پیشرفت شما هرگز از دستگاهتان خارج نمی‌شود.

موتورهای تولید پازل دست‌ساز، صفحه‌های آزموده شده و طراحی آرام و خلوت. فردا برای پازل بعدی برگردید.', description_fa_source = 'machine' WHERE package_name = 'com.joebywan.daybook' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'pitcher گام هر آهنگی را تغییر می‌دهد، در حالی که تمپو دقیقاً ثابت می‌ماند. موسیقی را از یک اکتاو کامل تا تنها یک سنت بالا یا پایین ببرید، گام را با تیونر داخلی پیدا کنید، با لوپ‌ها و سرعت‌های پایین‌تر تمرین کنید و نسخه دلخواهتان را به صورت فایل ذخیره کنید.

ساخته‌شده برای خوانندگانی که می‌خواهند آهنگ در وسعت صوتی صدایشان باشد، نوازندگانی که نیاز دارند ساز خود را با یک ضبط یا ساز دیگر هماهنگ کنند، و هر کسی که یک قطعه را به صورت گوشی یاد می‌گیرد.

تغییر زیروبمی
- روی صفحه به بالا یا پایین بکشید و هم‌زمان با پخش آهنگ، تغییرات را بشنوید.
- با گام‌های ۱، ۱۰ یا ۱۰۰ سنت جابه‌جا شوید، یک مقدار دقیق تایپ کنید، یا روی نیم‌پرده‌ها قفل شوید.
- فاصله موسیقایی هم‌زمان با تغییر شما نمایش داده می‌شود؛ برای مثال «یک سوم کوچک بالاتر».

پیدا کردن گام
- تیونر، نام نت را در محل پخش یا نشانک به همراه مقدار دقیق سنت آن مشخص می‌کند.
- نت مورد نظر خود را انتخاب کنید و فاصله را تنها با یک ضربه اعمال کنید.

تمرین
- لوپ‌ها برای بخش‌هایی که روی آن‌ها کار می‌کنید، با قابلیت تکرار به صورت تک‌تک یا متوالی.
- نشانک‌های نام‌گذاری‌شده که روی موج صوتی نمایش داده می‌شوند.
- سرعت پخش از نصف تا دو برابر، بدون تغییر زیروبمی.
- بزرگ‌نمایی موج صوتی و قابلیت دنبال کردن محل پخش.

نگهداری و ذخیره
- زیروبمی‌های مورد علاقه‌تان را در یک قفسه نگه دارید و با یک ضربه بین آن‌ها جابه‌جا شوید.
- زیروبمی‌های نگهداری‌شده در پس‌زمینه آماده می‌شوند، بنابراین ذخیره‌سازی بسیار سریع است.
- ذخیره یا به‌اشتراک‌گذاری به صورت WAV، MP3، M4A یا Opus؛ کل آهنگ یا فقط لوپ‌های شما، با سرعت معمولی یا سرعت تمرین.
- کیفیت فایل‌ها دقیقاً مانند پیش‌نمایش است، زیرا هر دو از یک موتور صوتی استفاده می‌کنند.

حفظ حریم خصوصی از پایه
- بدون دسترسی به شبکه. هیچ داده‌ای از گوشی شما خارج نمی‌شود.
