این برنامه بدون نیاز به حساب کاربری و بدون دسترسی به اینترنت کار می‌کند. داده‌های ثبت‌شده فقط روی دستگاه شما باقی می‌مانند. هیچ‌گونه تبلیغات، دورسنجی (telemetry)، ابزار تحلیلی (analytics)، همگام‌سازی ابری یا جمع‌آوری خودکار اطلاعات در پس‌زمینه وجود ندارد.

ویژگی‌ها:
• پیگیری روزانه حجم وعده‌ها
• نمای کلی و آمار مربوط به تاریخچه شخصی شما
• راهنمای حجم وعده‌ها با استفاده از دست و ظروف خانگی
• پشتیبان‌گیری و بازیابی محلی از طریق بخش انتخاب سند Android
• گزارش‌های محلی با فرمت PDF
• زبان‌های آلمانی، انگلیسی، اسپانیایی، فرانسوی، پرتغالی اروپایی، ترکی، عربی، لهستانی، روسی، اوکراینی و رومانیایی
• تم‌های روشن، تاریک و پاستلی دلنشین
• یک همراه محلی اختیاری که به طور پیش‌فرض غیرفعال است و به صورت جداگانه پشتیبان‌گیری می‌شود

این همراه فقط از توکن‌های درون‌برنامه‌ای که به صورت محلی به دست می‌آیند استفاده می‌کند. هیچ‌گونه خرید، تبلیغات یا ارتقای پولی وجود ندارد.

اطلاعات مربوط به وعده‌ها صرفاً جهت راهنمایی عمومی است. هرم استاندارد و راهنمای وعده‌ها از اطلاعات عمومی هرم غذایی BZfE (به‌روزرسانی شده در ۲۵ سپتامبر ۲۰۲۴) به عنوان منبع داده استفاده می‌کنند. برنامه Esca Agnellis یک پیاده‌سازی دیجیتال مستقل است، از هیچ‌یک از آثار هنری BZfE/BLE استفاده نمی‌کند و هیچ وابستگی، تأیید، پشتیبانی یا اسپانسری از سوی BZfE یا BLE ندارد. این برنامه توصیه پزشکی، رژیم غذایی یا مشاوره تغذیه‌ای اختصاصی محسوب نمی‌شود.

