UPDATE apps SET description_fa = 'Drift یک فیدخوان RSS و Atom مبتنی بر ذخیره‌سازی محلی (local-first) است. این برنامه فیدها را مستقیماً از منبع اصلی دریافت کرده و پایگاه داده SQLite اختصاصی خود را روی دستگاه شما نگه می‌دارد؛ بنابراین برنامه به‌طور کامل آفلاین کار می‌کند و برای عملکرد خود به هیچ سرویس شخص ثالثی وابسته نیست.

Drift یک نرم‌افزار رایگان و متن‌باز است که تحت مجوز AGPL-3.0-or-later منتشر شده است.

ویژگی‌های کلیدی:

* دریافت مستقیم فیدهای RSS و Atom بدون نیاز به سرور واسط
* ذخیره‌سازی محلی SQLite؛ اشتراک‌ها و تاریخچه مطالعه شما روی دستگاهتان باقی می‌ماند
* قابلیت وارد کردن و خروجی گرفتن OPML برای جابه‌جایی فیدها به دیگر فیدخوان‌ها و برعکس
* همگام‌سازی اختیاری self-hosted: اتصال Drift به ریلی (relay) همگام‌سازی شخصی خود برای هماهنگ نگه‌داشتن اشتراک‌ها و وضعیت مطالعه در دستگاه‌های مختلف. این ریلی فقط داده‌ها را بین دستگاه‌های خودتان جابه‌جا می‌کند، هرگز منبع اصلی داده‌ها نیست و کاملاً اختیاری است
* دریافت متن کامل مقالات برای فیدهایی که تنها خلاصه مطالب را منتشر می‌کنند
