UPDATE apps SET description_fa = 'ابزار بارگذاری فایل صوتی در Wikimedia Commons

برنامه Spell4Wiki یک نرم‌افزار موبایل برای ضبط و بارگذاری فایل‌های صوتی کلمات Wiktionary در Wikimedia Commons است. همچنین Spell4Wiki به‌عنوان یک واژه‌نامه چندزبانه ویکی عمل می‌کند.

ویژگی‌های برنامه:

Spell For Wiktionary - ضبط و بارگذاری فایل صوتی برای فهرست کلمات دسته‌بندی‌شده در Wiktionary
Spell For WordList - بارگذاری فایل صوتی برای فهرست‌های دلخواه کلمات از فایل‌های متنی یا کپی و پیست
Spell For Word - ضبط و بارگذاری تلفظ برای کلمات تکی
Wiktionary Search - جستجوی معانی کلمات از Wiktionary به چندین زبان

دستاوردهای برنامه Spell4Wiki:
• پشتیبانی از بیش از ۲۵۰ زبان برای هر ۴ ویژگی
• بارگذاری بیش از ۴۰,۰۰۰ فایل صوتی در Wikimedia Commons توسط مشارکت‌کنندگان زبان‌های مختلف
• دسته‌بندی تمام فایل‌های صوتی در Wikimedia Commons

هدف این برنامه
کلمات بسیار زیادی در Wiktionary وجود دارند، اما فایل‌های صوتی تلفظ برای آن‌ها کافی نیست. بنابراین، ما می‌توانیم تلفظ کلمات را به روشی ساده بارگذاری کنیم. همچنین می‌توانیم از این تلفظ‌ها تحت CC-license برای برنامه‌ریزی داده‌های ویکی و سایر فناوری‌ها مانند یادگیری ماشین استفاده کنیم و زبان‌شناسان دیگر نیز می‌توانند نحوه تلفظ کلمات را یاد بگیرند.

ویژگی‌های فنی:
• ضبط باکیفیت به فرمت WAV به همراه تبدیل به OGG
• فیلتر هوشمند برای بررسی کلماتی که از قبل دارای فایل صوتی هستند
• بارگذاری مستقیم در Wikimedia Commons با دسته‌بندی مناسب
• پشتیبانی از بیش از ۲۵۰ زبان

پشتیبانی‌شده توسط

VGLUG Foundation
Kaniyam Foundation، فعالان نرم‌افزار آزاد و
جامعه Wikimedia تامیل

نحوه استفاده
۱. ساخت حساب کاربری در Wikimedia Commons و ورود به آن (در صورت نداشتن حساب)
۲. انتخاب زبان خود از میان بیش از ۲۵۰ گزینه
۳. انتخاب حالت ضبط: Spell4Wiki، Spell4WordList یا Spell4Word
۴. ضبط تلفظ و بارگذاری در Wikimedia Commons

نکته
این برنامه برخی از جزئیات پیکربندی (فهرست زبان‌های موجود، دسته‌بندی‌ها و مشارکت‌کنندگان) را از repo برنامه بارگیری می‌کند.

