UPDATE apps SET description_fa = 'Materializr یک نرم‌افزار 3D CAD متن‌باز برای سازندگان (Makers) است؛ نقطه تعادلی بین ابزارهای بسیار ساده مثل Tinkercad و سوئیت‌های کاملاً حرفه‌ای نظیر FreeCAD. امکانات کافی برای مدل‌سازی حجمی (Solid Modeling) واقعی جهت ساخت قطعات کاربردی، بدون شیب تند یادگیری، نیاز به اشتراک یا ساخت حساب کاربری.

روی یک صفحه اسکتچ (Sketch) بکشید، آن را به جسم سه‌بعدی تبدیل کنید (Extrude، Revolve، Loft، Sweep)، لبه‌ها را گرد (Fillet) یا پخ‌دار (Chamfer) کنید، عملیات‌های Boolean را اجرا نمایید، رزوه ایجاد کنید و هر مرحله از تاریخچه طراحی را بعداً ویرایش کنید - حتی پس از بستن و باز کردن مجدد پروژه.

اسکتچ‌ها با مقیاس دقیق ۱:۱ میلی‌متر به فرمت SVG برای دستگاه‌های برش لیزر و CNC 2.5D خروجی گرفته می‌شوند. این برنامه همچنین فایل‌های STEP و IGES را وارد (Import) کرده و امکان خروجی گرفتن (Export) به فرمت‌های STEP، STL، IGES و glTF را دارد.

هسته هندسی (Geometry Kernel) برنامه OpenCASCADE است - اجسام صلب واقعی B-rep، نه مش‌ها (Meshes). رابط کاربری در Android قابلیت پشتیبانی از لمس دارد و برای تبلت‌ها و صفحه‌نمایش‌های بزرگ‌تر طراحی شده است (در گوشی‌های کوچک، پنل‌ها و نوارهای ابزار شلوغ و فشرده خواهند بود). باز کردن و ذخیره‌سازی فایل‌ها از طریق انتخاب‌گر سند سیستم (Storage Access Framework) انجام می‌شود؛ بنابراین هیچ دسترسی کلی به حافظه درخواست نمی‌شود.

این نرم‌افزار هنوز نوپاست و به‌سرعت توسعه یافته، بنابراین انتظار برخی اشکالات جزئی را داشته باشید. عملیات‌ها صحت نتایج خود را بررسی می‌کنند و در صورت بروز خطا متوقف می‌شوند تا خروجی خراب تولید نکنند؛ بنابراین یک اقدام ناموفق، مدل شما را دست‌نخورده باقی می‌گذارد - با این حال مرتباً پروژه خود را ذخیره کنید و لطفاً باگ‌ها را گزارش دهید.', description_fa_source = 'machine' WHERE package_name = 'com.materializr.app' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'توضیحات: monostr یک کلاینت Nostr برای Android همراه با قابلیت پرداخت انعام با Monero است.

همان Nostr، همان‌طور که می‌شناسید
• فید افرادی که دنبال می‌کنید، رشته‌گفتگوها (threads)، پروفایل‌ها همراه با تب‌های Posts و Replies
• لایک، repost، quote، پاسخ؛ منشن‌ها، هشتگ‌ها و لینک‌های قابل لمس
• تصاویر در نوت‌ها و آپلودهای شخصی شما (Blossom)، همراه با تار کردن محتوای حساس
• پیام‌های خصوصی (NIP-17)، بوکمارک‌ها و Muteهای خصوصی (NIP-51)
• جستجوی افراد و نوت‌ها (NIP-50)، اعلانات برای لایک‌ها، repostها، پاسخ‌ها و انعام‌ها (tips)
• لیست Relayهای شما (NIP-65)؛ اضافه شدن Relayهای نوشتن یک کاربر هنگام باز بودن پروفایل او
• ورود با Amber (NIP-55) یا کلید؛ تم روشن و تاریک، پشتیبانی از ۸ زبان

پرداخت انعام با Monero
• پرداخت انعام به یک نوت یا پروفایل از برنامه کیف پول شخصی خودتان (Unstoppable، monfluo، Cake ...) از طریق لینک monero:
• برنامه monostr هیچ کیف پول و کلید خرج‌کردنی (spend key) را نگهداری نمی‌کند
• برای دریافت انعام، آدرس و private view key خود را در یک watcher (به‌طور پیش‌فرض watcher.monostr.com یا watcher شخصی خودتان) ثبت می‌کنید. watcher پرداختی‌های ورودی شما را مشاهده کرده و رسیدهای امضاشده‌ی انعام را در Nostr منتشر می‌کند تا همه بتوانند انعام ثبت‌شده روی نوت را ببینند
• امکان پرداخت انعام به‌صورت ناشناس وجود دارد

متن‌باز
برنامه monostr یک نرم‌افزار آزاد است (AGPL-3.0-or-later). نوت‌ها، لایک‌ها و repostها عبارت «via monostr» را نشان می‌دهند (به‌طور پیش‌فرض خاموش است، اما قابل فعال‌سازی است). تعداد دنبال‌کنندگان می‌تواند از ایندکس Primal (یک سرویس اختصاصی) دریافت شود؛ این قابلیت نیز به‌طور پیش‌فرض خاموش است و امکان فعال‌سازی آن وجود دارد.

