UPDATE apps SET description_fa = 'Audile یک برنامه‌ی متن‌باز برای تشخیص موسیقی است که به شما کمک می‌کند قطعه‌های موسیقی در حال پخش در اطرافتان را به سرعت و با دقت بالا شناسایی کنید.
این برنامه از سرویس‌های AudD ،ACRCloud و Shazam برای شناسایی آهنگ استفاده کرده و از Odesli برای دریافت لینک‌های اختصاصی ترک در پلتفرم‌های مختلف بهره می‌برد.

ویژگی‌ها:

شناسایی - Audile به شما امکان می‌دهد تنها با یک کلیک، آهنگ‌ها را شناسایی کنید. در صورت عدم اتصال به اینترنت، فایل ضبط‌شده ذخیره می‌شود و پس از اتصال مجدد، فرآیند شناسایی ادامه می‌یابد. شما می‌توانید رفتار پیش‌فرض برنامه را در صورت عدم موفقیت در شناسایی (نبود اینترنت، عدم یافتن مورد مشابه، یا سایر خطاها) از طریق بخش تنظیمات شخصی‌سازی کنید.
استفاده در پس‌زمینه - به صورت یکپارچه و مستقیم از طریق پنل اعلان‌ها، widget صفحه اصلی، دکمه شناور یا tile تنظیمات سریع از برنامه استفاده کنید. فرآیند شناسایی را مدیریت کرده و اطلاعات ترک را بدون نیاز به باز کردن برنامه دریافت کنید.
درباره ترک - پس از شناسایی موفقیت‌آمیز، برنامه اطلاعات کاملی درباره ترک ارائه می‌دهد؛ از جمله عنوان، نام هنرمند، آلبوم، سال انتشار، کاور، متن آهنگ و لینک‌های دسترسی به آن در سرویس‌های محبوب موسیقی.
کتابخانه - تمامی ترک‌های شناسایی‌شده در کتابخانه‌ی برنامه ذخیره می‌شوند. شما می‌توانید لیست ترک‌ها را فیلتر کنید، لیستی از علاقه‌مندی‌ها بسازید، در میان ترک‌ها جستجو کنید یا آن‌ها را حذف نمایید.
تنظیمات - برنامه گزینه‌های متنوعی را برای شخصی‌سازی عملکرد و ظاهر خود ارائه می‌دهد که از طریق صفحه تنظیمات در دسترس هستند.', description_fa_source = 'machine' WHERE package_name = 'com.mrsep.musicrecognizer' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'SwiftSlate یک دستیار متنی هوش مصنوعی سراسری در سیستم برای Android است. کافی است یک محرک مانند «?fix» را در پایان هر متنی و در هر برنامه‌ای تایپ کنید و شاهد جایگزینی آنی آن باشید.

این برنامه در اکثر اپلیکیشن‌ها کار می‌کند — WhatsApp، Gmail، Twitter/X، Messages، Notes و موارد دیگر. بدون نیاز به کپی-پیست. بدون جابه‌جایی بین برنامه‌ها. فقط تایپ کنید و تمام.

ویژگی‌ها:

• عملکرد سراسری در سیستم از طریق Accessibility Service در Android
• قابلیت کار از منوی text-selection در هر برنامه‌ای — بدون نیاز به مجوز accessibility
• جایگزینی متن به‌صورت inline و آنی — پاسخ AI مستقیماً جایگزین متن شما می‌شود
• پشتیبانی از چند ارائه‌دهنده AI: Google Gemini، Groq یا هر اندپوینت سازگار با OpenAI (از جمله LLMهای محلی مانند Ollama و LM Studio)
• اجرای کاملاً آفلاین و بدون تاخیر دستورات جایگزین‌کننده متن (text replacer)
• چرخش چندکلیده (Multi-key rotation) با مدیریت خودکار محدودیت نرخ درخواست (rate-limit)
• رمزنگاری کلیدهای API با استاندارد AES-256-GCM از طریق Android Keystore
• تم تاریک AMOLED و تم روشن با طراحی Material 3
• بومی‌سازی‌شده به ۴۰ زبان — برنامه به‌طور خودکار از زبان دستگاه شما تبعیت می‌کند
• بدون هیچ‌گونه analytics، tracking یا telemetry
• حجم بسیار کم APK (حدود ۱.۷ مگابایت) بدون هیچ وابستگی شبکه‌ای به برنامه‌های شخص ثالث

دستورات پیش‌فرض:

• ?fix — اصلاح دستور زبان، املا و علائم نگارشی
• ?improve — بهبود وضوح و خوانایی
• ?shorten — کوتاه‌کردن متن با حفظ معنا
• ?expand — بسط دادن متن با جزئیات بیشتر
• ?formal — بازنویسی با لحن رسمی و حرفه‌ای
• ?casual — بازنویسی با لحن دوستانه و صمیمی
• ?emoji — افزودن ایموجی‌های مرتبط
• ?human — بازنویسی متن به‌گونه‌ای که شبیه به متن تولیدشده توسط AI به نظر نرسد
• ?reply — تولید پاسخ متناسب با زمینه متن (context)
• ?undo — بازگردانی متن به حالت قبل از آخرین جایگزینی
• ?translate:XX — ترجمه به هر زبان دلخواه
• ?copy / ?cut / ?paste / ?replace — انجام عملیات‌های Clipboard بدون خروج از کیبورد

شما همچنین می‌توانید دستورات AI سفارشی خود را با هر prompt دلخواهی بسازید، یا از دستورات text replacer برای درج آنی قطعه‌متن‌های آفلاین مانند امضاها، پاسخ‌های آماده و میانبرها استفاده کنید.

برای استفاده از دستورات AI، داشتن یک کلید API از Google Gemini (دارای سطح رایگان)، Groq یا هر ارائه‌دهنده سازگار با OpenAI الزامی است. دستورات text replacer بدون نیاز به هیچ کلید API کار می‌کنند.', description_fa_source = 'machine' WHERE package_name = 'com.musheer360.swiftslate' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'از Nextcloud Talk برای برقراری تماس‌های صوتی یا تصویری تک‌به‌تک یا گروهی، ایجاد یا پیوستن به وب‌کنفرانس‌ها و ارسال پیام‌های چت استفاده کنید. تمام ارتباطات به‌طور کامل رمزنگاری شده و از طریق سرور اختصاصی خودتان مدیریت می‌شوند تا بالاترین سطح حریم خصوصی ممکن را برای شما فراهم کنند.

استفاده از Nextcloud Talk آسان است و همیشه کاملاً رایگان خواهد بود!

Nextcloud Talk از امکانات زیر پشتیبانی می‌کند:
* تماس‌های صوتی/تصویری با کیفیت HD (H.265)
* تماس‌های گروهی و تک‌به‌تک
* وبینارها و جلسات آنلاین عمومی
* چت فردی و گروهی
* اشتراک‌گذاری آسان صفحه نمایش
* برنامه‌های موبایل برای Android و iOS
* Push Notification برای تماس‌ها و چت‌های موبایل (تنها در صورت نصب از Google Play)
* ادغام با Nextcloud Files و Nextcloud Groupware
* کاملاً قابل میزبانی در محل (on-premise) و کاملاً open source
* تماس‌های رمزنگاری‌شده سرتاسری (End-to-end Encrypted)
* قابلیت مقیاس‌پذیری برای میلیون‌ها کاربر
* درگاه SIP gate: شماره‌گیری و پیوستن از طریق تلفن

برنامه Nextcloud Talk برای کارکرد درست به یک سرور Nextcloud Talk نیاز دارد. Nextcloud یک پلتفرم خصوصی و self-hosted برای همگام‌سازی فایل‌ها و ارتباطات است که به منظور بازگرداندن کنترل داده‌ها به دست خودتان طراحی شده است. این پلتفرم روی سرور دلخواه شما اجرا می‌شود؛ چه در خانه، چه نزد یک ارائه‌دهنده خدمات یا در سازمان شما، و دسترسی به اسناد، تقویم‌ها، مخاطبین، ایمیل و سایر داده‌هایتان را فراهم می‌کند. شما می‌توانید اطلاعات را حتی میان سرورهای مختلف Nextcloud با دیگران به اشتراک بگذارید و به صورت مشترک روی اسناد کار کنید. Nextcloud کاملاً open source است و این امکان را به شما می‌دهد تا آن را برای استفاده خود توسعه دهید، در بهبود آن مشارکت کنید یا صرفاً صحت عملکرد آن را بررسی نمایید.

میلیون‌ها کاربر روزانه در کسب‌وکارها و خانه‌های سراسر جهان از Nextcloud استفاده می‌کنند. کاربران تجاری به پشتیبانی حرفه‌ای Nextcloud GmbH متکی هستند تا مطمئن شوند پلتفرمی کاملاً پشتیبانی‌شده و آماده برای استفاده سازمانی جهت بهره‌وری و همکاری در اختیار دارند که به‌طور کامل تحت کنترل دپارتمان IT آن‌هاست.

اطلاعات بیشتر در https://nextcloud.com/talk

Nextcloud را در https://nextcloud.com پیدا کنید', description_fa_source = 'machine' WHERE package_name = 'com.nextcloud.talk2' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
