- قابلیت Import/Export تنظیمات آپلودرها برای به اشتراک‌گذاری با دیگران، با پشتیبانی از فرمت آپلودر ShareX.
- همراه با پیش‌تنظیمات (Presets) داخلی برای آپلود.
- مجهز به یک URL parser قدرتمند که به شما امکان می‌دهد URL فایل آپلود شده را از پاسخ (Response) هاست استخراج کنید.', description_fa_source = 'machine' WHERE package_name = 'com.nyx.custom_uploader' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
UPDATE apps SET description_fa = 'برنامه TableChips جایگزین چیپ‌ها در بازی‌های واقعی کارت می‌شود که با یک دست کارت واقعی انجام می‌شوند. یک گوشی از طریق Hotspot خود، میز بازی را میزبانی می‌کند؛ بقیه افراد فقط یک کد را اسکن کرده و از طریق Browser، iPhone یا Android خود بازی می‌کنند. هیچ‌کس به اینترنت، حساب کاربری یا نصب هیچ برنامه‌ای نیاز ندارد.

این برنامه فقط چیپ‌ها را مدیریت می‌کند و نه هیچ چیز دیگری: هرگز کارت پخش نمی‌کند. شما مثل همیشه کارت‌ها را بر می‌زنید، پخش می‌کنید و بازی می‌کنید، و برنامه چیپ‌ها را می‌شمارد.

بازی‌ها

۷.۵ (set i mig) و Blackjack با بانک: همه در برابر بانک شرط‌بندی می‌کنند و بانک تسویه هر دست را از روی میز انجام می‌دهد.
Poker: دکمه متحرک، Blindها، مبالغ Call و Side potها.
حالت دستی برای هر بازی دیگری: Potها، شرط‌ها و پرداخت‌ها به‌صورت دستی.

چرا این برنامه؟

مهمانان نیازی به نصب هیچ چیزی ندارند. میزبان یک صفحه وب ارائه می‌دهد؛ کاربران iPhone و Android سر یک میز، فقط کافی است یک Browser باز کنند. هر کسی هم که برنامه را نصب داشته باشد، می‌تواند از طریق خود برنامه وارد شود.
بدون نیاز به اینترنت، برای همیشه. همه چیز روی Hotspot میزبان اجرا می‌شود: در کلبه کوهستانی، کمپ یا روستای بدون آنتن هم به‌راحتی کار می‌کند.
تا ۱۰ بازیکن، هر کدام روی دستگاه خود، با نمایش تعداد چیپ‌ها در اندازه‌ای بزرگ که از آن‌طرف میز هم خواناست.
امکان Undo نامحدود و تاریخچه کامل تمام حرکت‌ها. همیشه می‌توانید مبلغ را به‌صورت دستی هم تایپ کنید.
طراحی‌شده برای شب‌های طولانی: گوشی‌ها مجدداً متصل می‌شوند، جایگاه بازیکنان قابل بازیابی است و حتی با بستن برنامه توسط میزبان، اطلاعات میز حفظ می‌شود.
پشتیبانی از زبان‌های کاتالان، اسپانیایی و انگلیسی از همان صفحه اول.

برنامه TableChips چیپ‌ها را می‌شمارد. این برنامه هیچ‌گونه پول واقعی، پرداخت یا حساب کاربری ندارد؛ ارزش هر چیپ را خود افراد سر میز تعیین می‌کنند.

نرم‌افزار آزاد تحت مجوز GPLv3. بدون تبلیغات، بدون خرید درون‌برنامه‌ای و بدون ردیابی کاربران.', description_fa_source = 'machine' WHERE package_name = 'io.github.tablechips' AND description_fa IS NULL AND (description_fa_source IS NULL OR description_fa_source = 'machine');
